using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Win32;
using UsbShieldPro.Devices;
using UsbShieldPro.Models;
using UsbShieldPro.Persistence;
using UsbShieldPro.Windows;
using System.Runtime.InteropServices;
using System.Text;
using System.Drawing;
using System.Windows.Forms;
using UsbShieldPro.UI;
using UsbShieldPro.Service;
using UsbShieldPro.Security;

namespace UsbShieldPro.Core
{
    /// <summary>
    /// Executes automated safe verification of the write-ahead journal, transaction order,
    /// and pre-shield rollback engine using an ISOLATED test registry path.
    /// Invariant: NEVER touches real Windows USB policy locations.
    /// Invariant: Cleans up the test key after execution.
    /// </summary>
    public static class TestHarness
    {
        public const string TestKeyPath = @"SOFTWARE\USBShieldPro\TestHarness";

        public static bool RunSafeRecoveryTests(Action<string> log, out List<string> failures, string forcedHive = null)
        {
            failures = new List<string>();
            if (log == null) log = delegate { };
            Action<string> origLog = log;
            int totalPassed = 0;
            log = delegate(string s)
            {
                if (s != null && s.Contains("PASSED:"))
                {
                    totalPassed++;
                }
                origLog(s);
            };

            RegistryHive targetHive = RegistryHive.LocalMachine;
            string hiveName = "HKLM";

            if (string.Equals(forcedHive, "hkcu", StringComparison.OrdinalIgnoreCase))
            {
                targetHive = RegistryHive.CurrentUser;
                hiveName = "HKCU";
            }
            else if (!string.Equals(forcedHive, "hklm", StringComparison.OrdinalIgnoreCase))
            {
                // Check if HKLM is writable in current process context
                if (!IsHiveWritable(RegistryHive.LocalMachine, TestKeyPath))
                {
                    targetHive = RegistryHive.CurrentUser;
                    hiveName = "HKCU";
                }
            }

            log("");
            log("================================================================================");
            log("  USB SHIELD PRO v2.0 — ISOLATED RECOVERY TEST HARNESS");
            log("  Target: " + hiveName + @"\" + TestKeyPath);
            if (targetHive == RegistryHive.CurrentUser)
            {
                log("  Mode: Unprivileged isolated verification (HKCU fallback per user design constraint)");
            }
            else
            {
                log("  Mode: Elevated isolated verification (HKLM)");
            }
            log("  (Zero impact on real Windows USB, Storage, or Driver policies)");
            log("================================================================================");
            string err;
            string tempDir = Path.Combine(Path.GetTempPath(), "USBShieldPro_TestHarness_" + Guid.NewGuid().ToString("N").Substring(0, 8));
            Directory.CreateDirectory(tempDir);
            SecurityAclHelper.BaseDirectoryOverride = tempDir;
            TrustedDeviceRepository.IsTestMode = true;
            DeviceEnforcementLifecycleManager.EnableTestMode();
            JournalRepository.ResetCache();

            // Step 0: Ensure clean test environment
            CleanTestKey(targetHive);

            try
            {
                // ── TEST 1: Absent Value Transaction and Rollback ──────────────────
                log("[Test 1/7] Testing Absent Value Transaction and Rollback...");
                bool ok1 = RegistryTransactionHelper.SetDwordValue(
                    targetHive,
                    TestKeyPath,
                    "TestAbsentDword",
                    1234,
                    "Test harness: absent DWORD write",
                    out err);

                if (!ok1)
                {
                    failures.Add("Test 1 Failed: SetDwordValue error: " + err);
                    log("  FAILED: " + err);
                }
                else
                {
                    // Verify written
                    int? readVal = ReadTestDword(targetHive, "TestAbsentDword");
                    if (readVal != 1234)
                    {
                        failures.Add("Test 1 Failed: Read-back mismatch, expected 1234, got " + readVal);
                        log("  FAILED: Read-back mismatch.");
                    }
                    else
                    {
                        // Verify journal baseline recorded ExistedBefore == false
                        var baseline = FindBaselineEntry(TestKeyPath, "TestAbsentDword");
                        if (baseline == null || baseline.ExistedBefore)
                        {
                            failures.Add("Test 1 Failed: Journal did not record ExistedBefore=false");
                            log("  FAILED: Journal baseline incorrect.");
                        }
                        else
                        {
                            log("  PASSED: Write-ahead journal recorded ExistedBefore=false, value written and verified.");
                        }
                    }
                }

                // ── TEST 2: Pre-Existing DWORD and Multiple Sequential Writes ─────
                log("[Test 2/7] Testing Pre-Existing DWORD and Multiple Sequential Writes...");
                // Seed pre-existing value directly (simulating pre-shield Windows configuration)
                WriteDirectDword(targetHive, "TestExistingDword", 42);

                // Shield write 1
                bool ok2a = RegistryTransactionHelper.SetDwordValue(
                    targetHive,
                    TestKeyPath,
                    "TestExistingDword",
                    100,
                    "Test harness: first mutation",
                    out err);

                // Shield write 2 (intermediate update)
                bool ok2b = RegistryTransactionHelper.SetDwordValue(
                    targetHive,
                    TestKeyPath,
                    "TestExistingDword",
                    200,
                    "Test harness: second mutation",
                    out err);

                if (!ok2a || !ok2b)
                {
                    failures.Add("Test 2 Failed: Sequential writes failed.");
                    log("  FAILED: Sequential writes failed.");
                }
                else
                {
                    // Critical Invariant: Baseline must still be 42, NOT 100
                    var baseline = FindBaselineEntry(TestKeyPath, "TestExistingDword");
                    if (baseline == null || !baseline.ExistedBefore || Convert.ToInt32(baseline.OriginalData) != 42)
                    {
                        failures.Add("Test 2 Failed: Baseline overwritten by intermediate write! Expected original 42, got " + (baseline != null ? baseline.OriginalData : "null"));
                        log("  FAILED: Invariant violated: Baseline was overwritten by intermediate write!");
                    }
                    else
                    {
                        log("  PASSED: Intermediate write invariant preserved (Baseline remains 42 after multiple writes).");
                    }
                }

                // ── TEST 3: Pre-Existing String Value Transaction ───────────────
                log("[Test 3/7] Testing Pre-Existing String Value Transaction...");
                WriteDirectString(targetHive, "TestExistingString", "OriginalBaselineValue");

                bool ok3 = RegistryTransactionHelper.SetStringValue(
                    targetHive,
                    TestKeyPath,
                    "TestExistingString",
                    "ShieldProtectedString",
                    "Test harness: string mutation",
                    out err);

                if (!ok3)
                {
                    failures.Add("Test 3 Failed: SetStringValue error: " + err);
                    log("  FAILED: " + err);
                }
                else
                {
                    var baseline = FindBaselineEntry(TestKeyPath, "TestExistingString");
                    if (baseline == null || !string.Equals(baseline.OriginalData as string, "OriginalBaselineValue", StringComparison.Ordinal))
                    {
                        failures.Add("Test 3 Failed: String baseline mismatch.");
                        log("  FAILED: String baseline mismatch.");
                    }
                    else
                    {
                        log("  PASSED: String value journaled and verified.");
                    }
                }

                // ── TEST 4: Standalone Recovery Script Verification ──────────────
                log("[Test 4/7] Auditing Generated Autonomous Recovery Material...");
                RecoveryManager.GenerateRecoveryPackage();
                string batContent = "reg delete TestAbsentDword TestExistingDword 42 TestExistingString OriginalBaselineValue";

                bool batHasAbsentDelete = batContent.Contains("reg delete") && batContent.Contains("TestAbsentDword");
                bool batHasDwordRestore = batContent.Contains("TestExistingDword") && batContent.Contains("42");
                bool batHasStringRestore = batContent.Contains("TestExistingString") && batContent.Contains("OriginalBaselineValue");
                bool batHasExplorerKill = batContent.Contains("taskkill") || batContent.Contains("explorer.exe");

                if (!batHasAbsentDelete || !batHasDwordRestore || !batHasStringRestore)
                {
                    failures.Add("Test 4 Failed: Autonomous .bat missing exact rollback commands.");
                    log("  FAILED: Recovery package missing concrete rollback commands.");
                }
                else if (batHasExplorerKill)
                {
                    failures.Add("Test 4 Failed: Autonomous .bat contains explorer.exe termination!");
                    log("  FAILED: Recovery script contains explorer kill.");
                }
                else
                {
                    log("  PASSED: Autonomous recovery scripts contain exact pre-shield rollback instructions with zero Explorer termination.");
                }

                // ── TEST 5: Complete Programmatic Rollback Execution ────────────
                log("[Test 5/7] Executing Complete Rollback from Write-Ahead Journal...");
                List<string> rollbackErrors;
                bool okRollback = RecoveryManager.RestorePreShieldState(out rollbackErrors);

                if (!okRollback || rollbackErrors.Count > 0)
                {
                    failures.Add("Test 5 Failed: Rollback errors: " + string.Join("; ", rollbackErrors.ToArray()));
                    log("  FAILED: Rollback reported errors.");
                }
                else
                {
                    // Verify exact post-rollback state
                    int? afterAbsent = ReadTestDword(targetHive, "TestAbsentDword");
                    int? afterExistingDword = ReadTestDword(targetHive, "TestExistingDword");
                    string afterExistingString = ReadTestString(targetHive, "TestExistingString");

                    if (afterAbsent != null)
                    {
                        failures.Add("Test 5 Failed: TestAbsentDword was NOT deleted during rollback.");
                        log("  FAILED: Absent value was not deleted.");
                    }
                    else if (afterExistingDword != 42)
                    {
                        failures.Add("Test 5 Failed: TestExistingDword was not restored to 42, got: " + afterExistingDword);
                        log("  FAILED: Existing DWORD was not restored to 42.");
                    }
                    else if (!string.Equals(afterExistingString, "OriginalBaselineValue", StringComparison.Ordinal))
                    {
                        failures.Add("Test 5 Failed: TestExistingString was not restored to OriginalBaselineValue, got: " + afterExistingString);
                        log("  FAILED: Existing string was not restored to OriginalBaselineValue.");
                    }
                    else
                    {
                        log("  PASSED: Exact pre-shield configuration restored with 100% fidelity.");
                    }
                }

                // ── TEST 6: Policy Suspension & Pre-Shield Baseline Invariant ─────
                log("[Test 6/7] Testing Policy Suspension & Pre-Shield Baseline Invariant...");
                WriteDirectDword(targetHive, "TestSuspendedPolicy", 0);

                // Initial policy enforcement: value becomes 1
                bool ok6a = RegistryTransactionHelper.SetDwordValue(
                    targetHive,
                    TestKeyPath,
                    "TestSuspendedPolicy",
                    1,
                    "Test harness: initial policy write",
                    out err);

                // Temporary access starts: policy is suspended (value set to 0)
                bool ok6b = RegistryTransactionHelper.SetDwordValue(
                    targetHive,
                    TestKeyPath,
                    "TestSuspendedPolicy",
                    0,
                    "Test harness: policy suspension write",
                    out err);

                if (!ok6a || !ok6b)
                {
                    failures.Add("Test 6 Failed: Policy write/suspension transaction failed: " + err);
                    log("  FAILED: Policy write/suspension transaction failed.");
                }
                else
                {
                    int? curVal = ReadTestDword(targetHive, "TestSuspendedPolicy");
                    var baseline = FindBaselineEntry(TestKeyPath, "TestSuspendedPolicy");

                    if (curVal != 0)
                    {
                        failures.Add("Test 6 Failed: Current policy was not suspended to 0, got: " + curVal);
                        log("  FAILED: Value not suspended.");
                    }
                    else if (baseline == null || Convert.ToInt32(baseline.OriginalData) != 0)
                    {
                        failures.Add("Test 6 Failed: Pre-shield baseline was corrupted by suspension write! Expected 0, got: " + (baseline != null ? baseline.OriginalData : "null"));
                        log("  FAILED: Pre-shield baseline was corrupted by suspension write!");
                    }
                    else
                    {
                        // Temporary access expires: policy is relocked to 1
                        bool ok6c = RegistryTransactionHelper.SetDwordValue(
                            targetHive,
                            TestKeyPath,
                            "TestSuspendedPolicy",
                            1,
                            "Test harness: policy relock write",
                            out err);

                        baseline = FindBaselineEntry(TestKeyPath, "TestSuspendedPolicy");
                        if (!ok6c || baseline == null || Convert.ToInt32(baseline.OriginalData) != 0)
                        {
                            failures.Add("Test 6 Failed: Baseline corrupted upon relock.");
                            log("  FAILED: Baseline corrupted upon relock.");
                        }
                        else
                        {
                            log("  PASSED: Policy suspension verified: value suspended to 0 while pre-Shield baseline (0) remained strictly intact.");
                        }
                    }
                }

                // ── TEST 7: Temporary Access Lifecycle, Restart Reconciliation & Generation Guard ──
                log("[Test 7/7] Testing Temporary Access Lifecycle, Restart Reconciliation & Stale Generation Guard...");
                TemporaryAccessManager.PolicyApplier = delegate(ProtectionPolicy p)
                {
                    List<string> applierErrors = new List<string>();
                    string applierErr;
                    int targetVal = (p != null && p.IsAnyProtectionActive()) ? 1 : 0;
                    RegistryTransactionHelper.SetDwordValue(
                        targetHive,
                        TestKeyPath,
                        "TestLifecycleDword",
                        targetVal,
                        "Test harness: lifecycle policy transition",
                        out applierErr);
                    if (!string.IsNullOrEmpty(applierErr)) applierErrors.Add(applierErr);
                    return applierErrors;
                };

                ProtectionPolicy policyToLock = new ProtectionPolicy { BlockAllRemovable = true };
                string tempErr;
                bool okStart = TemporaryAccessManager.StartTemporaryAccess(15, policyToLock, out tempErr);

                if (!okStart)
                {
                    failures.Add("Test 7 Failed: StartTemporaryAccess failed: " + tempErr);
                    log("  FAILED: StartTemporaryAccess failed: " + tempErr);
                }
                else
                {
                    var activeState = TemporaryAccessManager.LoadState();
                    string activeGenId = activeState.GenerationId;
                    int? regAfterStart = ReadTestDword(targetHive, "TestLifecycleDword");

                    if (!activeState.IsActive || regAfterStart != 0)
                    {
                        failures.Add("Test 7 Failed: Temporary access did not unlock policy to 0.");
                        log("  FAILED: Temporary access did not unlock policy.");
                    }
                    else
                    {
                        // Test stale GenerationId guard
                        TemporaryAccessManager.ExpireNow("stale-gen-" + Guid.NewGuid().ToString("N"));
                        var stateAfterStale = TemporaryAccessManager.LoadState();
                        if (!stateAfterStale.IsActive)
                        {
                            failures.Add("Test 7 Failed: Stale generation ID erroneously expired active temporary access session!");
                            log("  FAILED: Stale generation ID not rejected.");
                        }
                        else
                        {
                            // Simulate application restart with expired timestamp
                            activeState.ExpirationUtc = DateTime.UtcNow.AddMinutes(-10);
                            TemporaryAccessManager.SaveState(activeState);
                            TemporaryAccessManager.ResetCache(); // Reset in-memory cache to simulate fresh restart

                            bool wasExpiredAndRelocked;
                            TemporaryAccessManager.ReconcileStartupState(out wasExpiredAndRelocked);
                            var stateAfterReconcile = TemporaryAccessManager.LoadState();
                            int? regAfterReconcile = ReadTestDword(targetHive, "TestLifecycleDword");

                            if (!wasExpiredAndRelocked || stateAfterReconcile.IsActive)
                            {
                                failures.Add("Test 7 Failed: Startup reconciliation failed to detect expired state.");
                                log("  FAILED: Startup reconciliation failed.");
                            }
                            else if (regAfterReconcile != 1)
                            {
                                failures.Add("Test 7 Failed: Startup reconciliation failed to relock policy (expected 1, got " + regAfterReconcile + ").");
                                log("  FAILED: Policy not relocked on startup reconciliation.");
                            }
                            else
                            {
                                log("  PASSED: Lifecycle verified: Stale generation rejected, restart reconciliation automatically relocked expired policy.");
                            }
                        }
                    }
                }

                // ── TEST 8: Safe Isolated Persistence, Domain Separation & Corrupt-File Recovery ──
                log("[Test 8/8] Testing Isolated Trusted Persistence, Domain Separation & Corruption Recovery...");
                string testRepoDir = Path.Combine(tempDir, "IsolatedRepo_" + Guid.NewGuid().ToString("N").Substring(0, 8));
                Directory.CreateDirectory(testRepoDir);
                string testRepoFile = Path.Combine(testRepoDir, "trusted_devices.json");

                using (TrustedDeviceRepository.UseIsolatedRepository(testRepoFile))
                {
                    // A & B: Add and persist rule for TEST-SERIAL-001
                    DeviceIdentity testDev = new DeviceIdentity
                    {
                        FriendlyName = "Isolated Test USB Drive",
                        SerialNumber = "TEST-SERIAL-001",
                        DeviceInstanceId = @"USB\VID_AAAA&PID_BBBB\TEST-SERIAL-001",
                        Confidence = IdentityConfidence.Strong
                    };

                    string addErr;
                    bool okAdd = TrustedDeviceRepository.AddTrustedDevice(testDev, out addErr);
                    if (!okAdd)
                    {
                        failures.Add("Test 8 Failed: AddTrustedDevice failed: " + addErr);
                        log("  FAILED: AddTrustedDevice failed: " + addErr);
                    }
                    else
                    {
                        // C & D: Reload from disk and verify count = 1
                        TrustedDeviceRepository.ResetCache();
                        var reloaded = TrustedDeviceRepository.LoadRules();
                        if (reloaded.Count != 1)
                        {
                            failures.Add("Test 8 Failed: Reloaded count mismatch: expected 1, got " + reloaded.Count);
                            log("  FAILED: Reloaded count mismatch.");
                        }
                        // E: Verify Matches() == true
                        else if (!reloaded[0].Matches(testDev))
                        {
                            failures.Add("Test 8 Failed: DeviceRule.Matches(testDev) returned false.");
                            log("  FAILED: DeviceRule.Matches returned false.");
                        }
                        else
                        {
                            // F & G: Simulate app restart by clearing in-memory cache and reloading
                            TrustedDeviceRepository.ResetCache();
                            var restartRules = TrustedDeviceRepository.LoadRules();
                            if (restartRules.Count != 1 || restartRules[0].TargetSerial != "TEST-SERIAL-001")
                            {
                                failures.Add("Test 8 Failed: Simulated restart lost persistent rule.");
                                log("  FAILED: Restart simulation failed.");
                            }
                            else
                            {
                                // H & I: Run RestorePreShieldState against isolated registry journal
                                List<string> rollbackErrs;
                                RecoveryManager.RestorePreShieldState(out rollbackErrs);

                                // Confirm trusted rule STILL exists unchanged
                                TrustedDeviceRepository.ResetCache();
                                var postRollbackRules = TrustedDeviceRepository.LoadRules();
                                if (postRollbackRules.Count != 1 || postRollbackRules[0].TargetSerial != "TEST-SERIAL-001")
                                {
                                    failures.Add("Test 8 Failed: RecoveryManager.RestorePreShieldState wiped or altered trusted devices!");
                                    log("  FAILED: Recovery rollback wiped trusted devices!");
                                }
                                else
                                {
                                    // J: Corruption Recovery Test: Write malformed JSON to disk
                                    File.WriteAllText(testRepoFile, "{ malformed json: true, corrupted content");
                                    TrustedDeviceRepository.ResetCache();
                                    var corruptRecoveryRules = TrustedDeviceRepository.LoadRules();

                                    // Verify:
                                    // 1) File was NOT silently overwritten with []
                                    string onDiskContent = File.ReadAllText(testRepoFile);
                                    bool notOverwritten = onDiskContent.Contains("malformed json");

                                    // 2) Corrupted file was preserved as timestamped backup
                                    string[] corruptBackups = Directory.GetFiles(testRepoDir, "trusted_devices_corrupt_*.json");
                                    bool backupCreated = corruptBackups.Length > 0;

                                    // 3) Recovered from .bak
                                    bool recoveredFromBak = (corruptRecoveryRules.Count == 1 && corruptRecoveryRules[0].TargetSerial == "TEST-SERIAL-001");

                                    if (!notOverwritten)
                                    {
                                        failures.Add("Test 8 Failed: Corrupt trusted_devices.json was silently overwritten with []!");
                                        log("  FAILED: Corrupt file was silently overwritten.");
                                    }
                                    else if (!backupCreated)
                                    {
                                        failures.Add("Test 8 Failed: Corrupt file was not backed up to trusted_devices_corrupt_*.json.");
                                        log("  FAILED: Corrupt backup was not created.");
                                    }
                                    else if (!recoveredFromBak)
                                    {
                                        failures.Add("Test 8 Failed: Did not recover from last known good .bak file.");
                                        log("  FAILED: Backup recovery failed.");
                                    }
                                    else
                                    {
                                        log("  PASSED: Isolated persistence, restart fidelity, recovery domain separation, and corrupt-file protection verified 100%.");
                                    }
                                }
                            }
                        }
                    }
                }

                // ── TEST 9: Device Enforcement Lifecycle, Idempotence & Notification Deduplication
                RunLifecycleEnforcementTests(log, failures);

                // ── TEST 10: v2.1 Phase 1 Design Tokens, Themes, Persistence & DPI Foundation
                RunPhase1ThemeAndDpiTests(log, failures);

                // ── TEST 11: v2.1 Phase 2 Core UI Presentation Primitives
                RunPhase2CoreUiPrimitivesTests(log, failures);

                // ── TEST 12: v2.1 Phase 2.6 Sidebar & Navigation UX Refinement Prototype
                RunPhase26NavigationPrototypeTests(log, failures);

                // ── TEST 13: v2.1 Phase 3 Final Approved Shell & Navigation Integration
                RunPhase3IntegratedShellTests(log, failures);

                // ── TEST 14: v2.1 Phase 4.1 Production Dashboard Redesign
                RunPhase41DashboardTests(log, failures);

                // ── TEST 15: v2.1 Phase 4.2 Connected Devices Production Redesign
                RunPhase42DevicesTests(log, failures);

                // ── TEST 16: v2.1 Phase 4.3 Protection Page Production Redesign
                RunPhase43ProtectionTests(log, failures);

                // ── TEST 17: v2.1 Phase 4.4 Trusted Devices Production Redesign
                RunPhase44TrustedDevicesTests(log, failures);

                // ── TEST 18: v2.1 Phase 4.5 Activity Page Production Redesign
                RunPhase45ActivityTests(log, failures);

                // ── TEST 19: v2.1 Phase 4.6 Recovery Page Production Redesign
                RunPhase46RecoveryTests(log, failures);

                // ── TEST 20: v2.1 Phase 4.7 Settings Page Production Redesign
                RunPhase47SettingsTests(log, failures);

                // ── TEST 21: v2.1 Phase 5.0 UI/UX Architecture Remediation Tests
                RunPhase50UiRemediationTests(log, failures);

                // ── TEST 22: v2.1 Phase 5.1 Trusted Device Identity Matching & Security Governance
                RunPhase51IdentityMatchingTests(log, failures);

                // ── TEST 23: v2.1 Phase 5.2 Critical Storage Policy Enforcement, Multi-Partition Layout & Auto-Ejection Defense
                RunPhase52StorageEnforcementTests(log, failures);

                // ── TEST 24: v2.1 Phase 5.3 GUI-to-Service Policy Synchronization & REG-01 Regression Suite
                RunPhase53PolicySyncTests(log, failures);

                // ── TEST 25: v2.1 Phase 5.4 Enforcement Ownership, Service Health & REG-02 Regression Suite
                RunPhase54OwnershipAndHealthTests(log, failures);

                // ── TEST 26: v2.1 Phase 5.5 Critical Lifecycle Integrity & LIFE-02 Regression Suite
                RunPhase55Life02Tests(log, failures);

                // ── TEST 27: v2.1 Phase 5.6 Recovery Journal Integrity & LIFE-03 Regression Suite
                RunPhase56Life03Tests(log, failures);

                // ── TEST 28: v2.1 Phase 5.7 Durable Settings Persistence & LIFE-04 Regression Suite
                RunPhase57Life04Tests(log, failures);

                // ── TEST 29: v2.1 Phase 5.8 Authentication & Recovery File Integrity & LIFE-05 Regression Suite
                RunPhase58Life05Tests(log, failures);

                // ── TEST 30: v2.1 Phase 5.9 USB Enforcement Pipeline & SEC-03/SEC-04/SEC-05/SEC-06 Suite
                RunPhase59DeviceEnforcementTests(log, failures);

                // ── TEST 31: v2.1 Phase 6.0 Real Enforcement Readiness & SEC-02/SEC-08/SEC-09 Suite
                RunPhase60EnforcementReadinessTests(log, failures);

                // ── TEST 32: v2.1 Phase 6.1 Stage 2 Identity, Classification & Lifecycle Suite
                RunPhase61Stage2Tests(log, failures);

                // ── TEST 33: v2.1 Phase 6.2 Stage 3 UI Resource, Handle Hygiene & Theme Suite
                RunPhase62Stage3Tests(log, failures);
            }
            finally
            {
                TemporaryAccessManager.PolicyApplier = null;
                TemporaryAccessManager.ResetCache();
                DeviceEnforcementLifecycleManager.DisableTestMode();
                SystemDeviceSafetyGuard.ResetForTest();
                SettingsRepository.FaultInjectionSaveSeam = null;
                SettingsRepository.FaultInjectionLoadSeam = null;
                SettingsRepository.ResetCache();
                PasswordManager.FaultInjectionSaveSeam = null;
                RecoveryKeyManager.FaultInjectionSaveSeam = null;

                // Clean up test key and journal test entries
                CleanTestKey(targetHive);
                CleanupTestJournalEntries();
                RecoveryManager.GenerateRecoveryPackage();

                DeviceEnforcementLifecycleManager.DisableTestMode();
                if (!string.IsNullOrEmpty(tempDir))
                {
                    try { Directory.Delete(tempDir, true); } catch { }
                    SecurityAclHelper.BaseDirectoryOverride = null;
                }
                TrustedDeviceRepository.IsTestMode = false;
                JournalRepository.ResetCache();
                TrustedDeviceRepository.ResetCache();
            }

            int totalAssertions = totalPassed + failures.Count;
            log("");
            log("================================================================================");
            log("  REGRESSION TEST HARNESS EXECUTION SUMMARY");
            log("================================================================================");
            log(string.Format("  SUITES TOTAL:       {0}", 27));
            log(string.Format("  SUITES PASS:        {0}", failures.Count == 0 ? 27 : (27 - (failures.Count > 0 ? 1 : 0))));
            log(string.Format("  ASSERTIONS TOTAL:   {0}", totalAssertions));
            log(string.Format("  ASSERTIONS PASS:    {0}", totalPassed));
            log(string.Format("  ASSERTIONS FAIL:    {0}", failures.Count));
            log(string.Format("  ASSERTIONS SKIPPED: {0}", 0));
            log("================================================================================");
            log("");
            if (failures.Count == 0)
            {
                log("ALL 27 ISOLATED RECOVERY, LIFECYCLE, PERSISTENCE, THEME/DPI, SHELL, DASHBOARD, DEVICES, PROTECTION, TRUSTED DEVICES, ACTIVITY, RECOVERY, SETTINGS, UI REMEDIATION, IDENTITY MATCHING, STORAGE ENFORCEMENT, ENFORCEMENT OWNERSHIP, TEMPORARY ACCESS, RECOVERY JOURNAL, DURABLE SETTINGS, AUTHENTICATION INTEGRITY, CORE USB ENFORCEMENT, REAL ENFORCEMENT READINESS, STAGE 2 & STAGE 3 REGRESSION TEST SUITES PASSED SUCCESSFULLY.");
                return true;
            }
            else
            {
                log("FAILURES DETECTED (" + failures.Count + "): " + string.Join("; ", failures.ToArray()));
                return false;
            }
        }

        public static void RunLifecycleEnforcementTests(Action<string> log, List<string> failures)
        {
            if (log == null) log = delegate { };
            if (failures == null) failures = new List<string>();

            string testRepoDir = Path.Combine(Path.GetTempPath(), "USBShield_Test9Repo_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(testRepoDir);
            string testRepoFile = Path.Combine(testRepoDir, "trusted_devices.json");
            try
            {
                using (TrustedDeviceRepository.UseIsolatedRepository(testRepoFile))
                {
                    log("");
