                                           form.PostureCard.Badge.Text == "Unprotected" &&
                                           form.PostureCard.Badge.Variant == StatusBadgeVariant.Neutral);
                        postureUnprotectedOk = topUnprot && cardUnprot;
                    }

                    bool all16I = postureProtectedOk && postureMismatchOk && postureUnprotectedOk && noContradictionEver;
                    if (!all16I)
                    {
                        failures.Add(string.Format("Test 16I Failed: protectedOk={0}, mismatchOk={1}, unprotOk={2}, noContradiction={3}",
                            postureProtectedOk, postureMismatchOk, postureUnprotectedOk, noContradictionEver));
                        log("  FAILED: TopBar and Protection page posture states diverged or contradicted.");
                    }
                    else
                    {
                        log("  PASSED: TopBar and Protection page posture consistency verified across Protected, Mismatch, and Unprotected states with zero contradictory presentation.");
                    }

                    // ── TEST 16J: Semantic Truthfulness, Toggle Green Presentation & Advanced Copy ──
                    log("[Test 16J] Protection Page — Semantic Truthfulness, Success Green Toggles & Verified Copy...");
                    bool noKernelClaimsOk = false;
                    bool sentinelTruthfulOk = false;
                    bool autoplayTruthfulOk = false;
                    bool toggleSemanticSuccessOk = false;
                    bool advancedSourceBackedOk = false;

                    // 1. Audit Kernel Claims removal in EN and AR
                    Loc.Current = Language.English;
                    string enPostureDesc = Loc.Get("PostureProtectedDesc");
                    Loc.Current = Language.Arabic;
                    string arPostureDesc = Loc.Get("PostureProtectedDesc");
                    Loc.Current = Language.English;

                    bool enNoKernel = !enPostureDesc.ToLowerInvariant().Contains("kernel") && enPostureDesc.Contains("matches the configured protection");
                    bool arNoKernel = !arPostureDesc.Contains("نواة") && arPostureDesc.Contains("مطابقة لإعدادات الحماية");
                    noKernelClaimsOk = enNoKernel && arNoKernel;

                    // 2. Audit Sentinel Reactive wording (No "immediately upon arrival" / "فور توصيلها")
                    Loc.Current = Language.English;
                    string enSentinelDesc = Loc.Get("RuleBlockFlashOnlyDesc");
                    Loc.Current = Language.Arabic;
                    string arSentinelDesc = Loc.Get("RuleBlockFlashOnlyDesc");
                    Loc.Current = Language.English;

                    bool enNoInstant = !enSentinelDesc.ToLowerInvariant().Contains("immediately upon arrival") && enSentinelDesc.Contains("Monitors newly detected USB flash drives");
                    bool arNoInstant = !arSentinelDesc.Contains("فور توصيلها") && arSentinelDesc.Contains("يراقب وسائط فلاش USB المكتشفة حديثًا");
                    sentinelTruthfulOk = enNoInstant && arNoInstant;

                    // 3. Audit AutoPlay Guard truthful wording
                    Loc.Current = Language.English;
                    string enAutoPlay = Loc.Get("RuleAutoPlayGuardDesc");
                    string enAutoPlayTip = Loc.Get("TooltipAutoPlayGuard");
                    Loc.Current = Language.Arabic;
                    string arAutoPlay = Loc.Get("RuleAutoPlayGuardDesc");
                    Loc.Current = Language.English;

                    autoplayTruthfulOk = enAutoPlay.Contains("Suppresses automatic handling and launch interactions") &&
                                         arAutoPlay.Contains("يمنع المعالجة التلقائية وتفاعلات التشغيل التلقائي") &&
                                         enAutoPlayTip.Contains("Not antivirus") &&
                                         enAutoPlayTip.Contains("BadUSB");

                    // 4. Audit ProtectionSettingRow Toggles: UseSemanticSuccessTrack == true
                    using (MainForm form = new MainForm())
                    {
                        form.TriggerSwitchTab(2);
                        bool t1 = form.RowRemovableDisks != null && form.RowRemovableDisks.Toggle.UseSemanticSuccessTrack;
                        bool t2 = form.RowReadOnly != null && form.RowReadOnly.Toggle.UseSemanticSuccessTrack;
                        bool t3 = form.RowPhones != null && form.RowPhones.Toggle.UseSemanticSuccessTrack;
                        bool t4 = form.RowWhitelist != null && form.RowWhitelist.Toggle.UseSemanticSuccessTrack;
                        bool t5 = form.RowFlashSentinel != null && form.RowFlashSentinel.Toggle.UseSemanticSuccessTrack;
                        bool t6 = form.RowAutoPlayGuard != null && form.RowAutoPlayGuard.Toggle.UseSemanticSuccessTrack;
                        bool t7 = form.RowStrictPnp != null && form.RowStrictPnp.Toggle.UseSemanticSuccessTrack;
                        bool t8 = form.RowHardBlock != null && form.RowHardBlock.Toggle.UseSemanticSuccessTrack;
                        toggleSemanticSuccessOk = t1 && t2 && t3 && t4 && t5 && t6 && t7 && t8;
                    }

                    // 5. Audit USBSTOR Driver Hard Block source-backed copy
                    Loc.Current = Language.English;
                    string enHardBlockDesc = Loc.Get("RuleHardBlockDesc");
                    string enHardBlockTip = Loc.Get("TooltipHardBlock");
                    Loc.Current = Language.Arabic;
                    string arHardBlockDesc = Loc.Get("RuleHardBlockDesc");
                    Loc.Current = Language.English;

                    advancedSourceBackedOk = (enHardBlockDesc.Contains("USBSTOR Start=4") || enHardBlockDesc.Contains("USB storage")) &&
                                             (arHardBlockDesc.Contains("USBSTOR Start=4") || arHardBlockDesc.Contains("USB")) &&
                                             (enHardBlockTip.Contains("Start=4") || enHardBlockTip.Contains("USB storage"));

                    bool all16J = noKernelClaimsOk && sentinelTruthfulOk && autoplayTruthfulOk && toggleSemanticSuccessOk && advancedSourceBackedOk;
