        // ═══════════════════════════════════════════════════════════════════════════
        // TEST 26: v2.1 Phase 5.5 Critical Lifecycle Integrity & LIFE-02 Regression Suite
        // ═══════════════════════════════════════════════════════════════════════════
        public static void RunPhase55Life02Tests(Action<string> log, List<string> failures)
        {
