            log("  [Test 26] v2.1 Phase 5.5 Critical Lifecycle Integrity & LIFE-02 Regression Suite");
            log("  Permanent Regression Suite for Pre-Commit Durable Lease Invariant, Clock");
            log("  Tampering Defense, Relock Failure Retention, and Startup Lease Reconciliation");
            log("================================================================================");

            string testDir = Path.Combine(Path.GetTempPath(), "UsbShield_Test26_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(testDir);
