            var origSaveSeam = TemporaryAccessManager.FaultInjectionSaveStateSeam;
            var origRelockSeam = TemporaryAccessManager.FaultInjectionRelockSeam;
            var origPolicyApplier = TemporaryAccessManager.PolicyApplier;
            var origOwnerOverride = EnforcementOwnerResolver.ResolveOwnerOverride;
            var origIpcSeam = ServiceManager.SendIpcRequestOverride;

