                int applyCallCount = 0;
                TemporaryAccessManager.PolicyApplier = delegate(ProtectionPolicy p)
                {
                    applyCallCount++;
                    return new List<string>();
                };

                // Fault injection: Simulate disk write failure during lease save
                TemporaryAccessManager.FaultInjectionSaveStateSeam = delegate { return "Simulated out of disk space on lease persistence"; };

                string err26A;
                ProtectionPolicy adminBasePolicy = new ProtectionPolicy { BlockAllRemovable = true, BlockRemovableDisks = true };
                bool startOk = TemporaryAccessManager.StartTemporaryAccess(30, adminBasePolicy, out err26A);

                // Verify: start must fail, error reported, and PolicyApplier NEVER called (Windows policy untouched)
                bool pass26A = (!startOk) &&
                               (err26A != null && err26A.Contains("Simulated out of disk space")) &&
                               (applyCallCount == 0);

                if (!pass26A)
                {
                    failures.Add(string.Format("Test 26A Failed: startOk={0}, err={1}, applyCalls={2} (expected false, disk err, 0)",
                        startOk, err26A, applyCallCount));
                    log("  FAILED: Storage policy was unlocked or failure was ignored when lease write failed.");
                }
                else
                {
                    log("  PASSED: Pre-commit invariant enforced: policy remains locked and lease rejected when persistence fails.");
                }

                // ── TEST 26B: Clock Tampering & Backward Rollback Protection ──
                log("[Test 26B] Clock Tampering & Backward Rollback Protection...");
                TemporaryAccessManager.FaultInjectionSaveStateSeam = null;
                applyCallCount = 0;

                // Create a lease whose StartUtc is in the future by 10 minutes (simulating system clock rolled back)
                TemporaryAccessState clockTamperState = new TemporaryAccessState
                {
                    Status = TemporaryAccessStatus.Active,
                    IsActive = true,
                    StartUtc = DateTime.UtcNow.AddMinutes(10),
                    ExpirationUtc = DateTime.UtcNow.AddMinutes(25),
                    TotalMinutes = 15,
                    OriginalDesiredPolicy = adminBasePolicy,
                    GenerationId = "GEN_CLOCK_TAMPER"
                };
                string saveErr;
                TemporaryAccessManager.SaveState(clockTamperState, out saveErr);

                // Query remaining seconds: MUST detect clock rollback and trigger immediate relock
                int remSec = TemporaryAccessManager.GetRemainingSeconds();
                TemporaryAccessState afterClockCheck = TemporaryAccessManager.LoadState();

                bool pass26B = (remSec == 0) &&
                               (afterClockCheck != null && afterClockCheck.Status == TemporaryAccessStatus.Relocked && !afterClockCheck.IsActive) &&
                               (applyCallCount == 1);

                if (!pass26B)
                {
                    failures.Add(string.Format("Test 26B Failed: remSec={0}, status={1}, isActive={2}, applyCalls={3}",
