                    log("  PASSED: Backward clock adjustment detected; lease expired and deterministic re-lock executed.");
                }

                // ── TEST 26C: Re-Lock Failure Retention & Observability ──
                log("[Test 26C] Re-Lock Failure Retention & Observability (Zero Silent Unrestricted Access)...");
                // Start a fresh valid temporary access session
                applyCallCount = 0;
                string err26C;
                bool freshStartOk = TemporaryAccessManager.StartTemporaryAccess(15, adminBasePolicy, out err26C);

                // Inject failure on re-lock policy application
                TemporaryAccessManager.FaultInjectionRelockSeam = delegate(ProtectionPolicy p)
                {
                    return "Simulated registry access denied during re-lock";
                };

                string relockErr26C;
                bool relockOk = TemporaryAccessManager.ExpireNow(null, out relockErr26C);
                TemporaryAccessState failedState = TemporaryAccessManager.LoadState();

                bool pass26C_1 = (!relockOk) &&
                                 (failedState != null && failedState.Status == TemporaryAccessStatus.RelockFailed) &&
                                 (!failedState.IsActive) &&
                                 (failedState.RelockAttempts == 1) &&
                                 (failedState.LastRelockError != null && failedState.LastRelockError.Contains("Simulated registry access denied"));

                // Clear injection seam and retry re-lock via ExpireNow
                TemporaryAccessManager.FaultInjectionRelockSeam = null;
                string retryErr;
                bool retryOk = TemporaryAccessManager.ExpireNow(null, out retryErr);
                TemporaryAccessState recoveredState = TemporaryAccessManager.LoadState();

                bool pass26C_2 = retryOk &&
                                 (recoveredState != null && recoveredState.Status == TemporaryAccessStatus.Relocked) &&
                                 (!recoveredState.IsActive) &&
                                 (recoveredState.LastRelockError == null);

                bool pass26C = pass26C_1 && pass26C_2;
                if (!pass26C)
                {
                    failures.Add(string.Format("Test 26C Failed: p1={0} (status={1}, attempts={2}, err={3}), p2={4} (retryOk={5}, status={6})",
                        pass26C_1, failedState != null ? failedState.Status.ToString() : "null",
                        failedState != null ? failedState.RelockAttempts.ToString() : "null",
                        failedState != null ? failedState.LastRelockError : "null",
                        pass26C_2, retryOk, recoveredState != null ? recoveredState.Status.ToString() : "null"));
                    log("  FAILED: Re-lock failure was not retained as observable pending obligation or retry failed.");
                }
                else
                {
                    log("  PASSED: Failed re-lock preserved as RelockFailed obligation without silent unrestricted access; subsequent retry succeeded.");
                }

                // ── TEST 26D: Cold Restart & Service Interruption Reconciliation ──
                log("[Test 26D] Cold Restart & Service Interruption Lease Reconciliation...");
                applyCallCount = 0;

                // Subcase 1: Machine restarted while lease is still valid
                TemporaryAccessState validActiveState = new TemporaryAccessState
                {
                    Status = TemporaryAccessStatus.Active,
                    IsActive = true,
                    StartUtc = DateTime.UtcNow.AddMinutes(-5),
                    ExpirationUtc = DateTime.UtcNow.AddMinutes(15),
                    TotalMinutes = 20,
                    OriginalDesiredPolicy = adminBasePolicy,
                    GenerationId = "GEN_ACTIVE_RESTART"
                };
                TemporaryAccessManager.SaveState(validActiveState);

                bool wasRelocked1;
                string relockErr1;
                TemporaryAccessManager.ReconcileStartupState(out wasRelocked1, out relockErr1);
                TemporaryAccessState loadedActive = TemporaryAccessManager.LoadState();

                bool pass26D_1 = (!wasRelocked1) &&
                                 (loadedActive != null && loadedActive.Status == TemporaryAccessStatus.Active && loadedActive.IsActive) &&
                                 (applyCallCount == 0);

                // Subcase 2: Machine restarted AFTER lease expired offline
                TemporaryAccessState expiredState = new TemporaryAccessState
                {
                    Status = TemporaryAccessStatus.Active,
                    IsActive = true,
                    StartUtc = DateTime.UtcNow.AddHours(-2),
                    ExpirationUtc = DateTime.UtcNow.AddHours(-1),
                    TotalMinutes = 60,
                    OriginalDesiredPolicy = adminBasePolicy,
                    GenerationId = "GEN_EXPIRED_RESTART"
                };
                TemporaryAccessManager.SaveState(expiredState);

                bool wasRelocked2;
                string relockErr2;
                TemporaryAccessManager.ReconcileStartupState(out wasRelocked2, out relockErr2);
                TemporaryAccessState loadedExpired = TemporaryAccessManager.LoadState();

                bool pass26D_2 = wasRelocked2 &&
                                 (loadedExpired != null && loadedExpired.Status == TemporaryAccessStatus.Relocked && !loadedExpired.IsActive) &&
                                 (applyCallCount == 1);

                bool pass26D = pass26D_1 && pass26D_2;
                if (!pass26D)
                {
                    failures.Add(string.Format("Test 26D Failed: subcase1={0} (wasRelocked={1}, status={2}), subcase2={3} (wasRelocked={4}, status={5})",
                        pass26D_1, wasRelocked1, loadedActive != null ? loadedActive.Status.ToString() : "null",
                        pass26D_2, wasRelocked2, loadedExpired != null ? loadedExpired.Status.ToString() : "null"));
                    log("  FAILED: Cold restart startup reconciliation failed to handle active or expired lease.");
                }
                else
                {
                    log("  PASSED: Startup reconciliation preserved active lease and cleanly re-locked expired lease upon initialization.");
                }

                // ── TEST 26E: ServiceManager IPC Routing & Fallback Integration ──
                log("[Test 26E] ServiceManager IPC Routing & Authoritative Ownership Integration...");
                // Case 1: Service is authoritative
                EnforcementOwnerResolver.ResolveOwnerOverride = delegate { return EnforcementOwnerState.Service; };
                string capturedIpcCmd = null;
                string capturedIpcPayload = null;
                ServiceManager.SendIpcRequestOverride = delegate(string cmd, string p, int timeout)
                {
                    capturedIpcCmd = cmd;
                    capturedIpcPayload = p;
                    return new IpcResponse { Success = true };
                };

                string smErr1;
                bool smOk1 = ServiceManager.StartTemporaryAccess(45, adminBasePolicy, out smErr1);
                string cancelIpcCmd = null;
                ServiceManager.SendIpcRequestOverride = delegate(string cmd, string p, int timeout)
                {
                    cancelIpcCmd = cmd;
                    return new IpcResponse { Success = true };
                };
                string smErrCancel;
                bool smCancelOk = ServiceManager.CancelTemporaryAccess(out smErrCancel);

                bool pass26E_1 = smOk1 && (capturedIpcCmd == "SETTEMPORARYACCESS") && (capturedIpcPayload == "45") &&
                                 smCancelOk && (cancelIpcCmd == "CANCELTEMPORARYACCESS");

                // Case 2: Service stopped -> GuiFallback routes to local TemporaryAccessManager
                EnforcementOwnerResolver.ResolveOwnerOverride = delegate { return EnforcementOwnerState.GuiFallback; };
                TemporaryAccessManager.PolicyApplier = delegate(ProtectionPolicy p) { return new List<string>(); };
                string smErr2;
                bool smOk2 = ServiceManager.StartTemporaryAccess(20, adminBasePolicy, out smErr2);
                TemporaryAccessState fallbackState = TemporaryAccessManager.LoadState();

                bool pass26E_2 = smOk2 && (fallbackState != null && fallbackState.Status == TemporaryAccessStatus.Active);

                bool pass26E = pass26E_1 && pass26E_2;
                if (!pass26E)
                {
                    failures.Add(string.Format("Test 26E Failed: serviceIpc={0} (ok={1}, cmd={2}, p={3}), fallback={4} (ok={5}, status={6})",
                        pass26E_1, smOk1, capturedIpcCmd, capturedIpcPayload,
                        pass26E_2, smOk2, fallbackState != null ? fallbackState.Status.ToString() : "null"));
                    log("  FAILED: ServiceManager did not correctly route temporary access commands according to authoritative owner.");
                }
                else
                {
                    log("  PASSED: ServiceManager correctly routed temporary access to Service over IPC and fell back to local manager in GuiFallback.");
                }
            }
            finally
