                    log("  PASSED: Exact pre-shield configuration restored: DWORD=42, String='PreShieldValue', AbsentVal deleted, and BaselineRestored verified.");
                }
            }
            finally
            {
                DeviceEnforcementLifecycleManager.DisableTestMode();
                SecurityAclHelper.BaseDirectoryOverride = origOverride;
                JournalRepository.FaultInjectionLoadSeam = null;
                JournalRepository.FaultInjectionSaveSeam = null;
                RegistryTransactionHelper.KeyPathRewriter = null;
                RegistryTransactionHelper.HiveOverride = null;
                JournalRepository.ResetCache();
                try
                {
                    if (Directory.Exists(testDir)) Directory.Delete(testDir, true);
                }
                catch { }
            }
        }

        // ═══════════════════════════════════════════════════════════════════════════
        // TEST 28: v2.1 Phase 5.7 Durable Settings Persistence & LIFE-04 Regression Suite
        // ═══════════════════════════════════════════════════════════════════════════
        public static void RunPhase57Life04Tests(Action<string> log, List<string> failures)
        {
            if (log == null) log = delegate { };
            if (failures == null) failures = new List<string>();

            log("");
            log("================================================================================");
            log("  [Test 28] v2.1 Phase 5.7 Durable Settings Persistence & LIFE-04 Regression Suite");
            log("  Permanent Regression Suite for Cache Advance Gating, Write Failure Isolation,");
            log("  Atomic Replace with Backup Creation, and Backup Recovery Fallback");
            log("================================================================================");

            string testDir = Path.Combine(Path.GetTempPath(), "UsbShield_Test28_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(testDir);
            string origOverride = SecurityAclHelper.BaseDirectoryOverride;
            SecurityAclHelper.BaseDirectoryOverride = testDir;

            System.Web.Script.Serialization.JavaScriptSerializer serializer = new System.Web.Script.Serialization.JavaScriptSerializer();

            try
            {
                DeviceEnforcementLifecycleManager.EnableTestMode();
                // ── TEST 28A: Save Failure Does NOT Advance Cache ──
                log("[Test 28A] Persistence Failure Gating: In-Memory Cache Must Not Advance on Disk Failure...");
                SettingsRepository.ResetCache();

                // 1. Establish known baseline in settings
                AppSettingsData baseline = new AppSettingsData();
                baseline.ThemePreference = "InitialBaselineTheme";
                baseline.LanguagePreference = "en";
                string saveErr;
                bool initialSaveOk = SettingsRepository.Save(baseline, out saveErr);

                // Verify initial save succeeded and cache has baseline
                AppSettingsData cachedBefore = SettingsRepository.Load();
                bool baselineOk = initialSaveOk && cachedBefore != null && cachedBefore.ThemePreference == "InitialBaselineTheme";

                // 2. Inject failure seam to simulate disk failure / access denied
                SettingsRepository.FaultInjectionSaveSeam = delegate(AppSettingsData s)
                {
                    return "Simulated Access Denied / Disk Full";
                };

                // 3. Attempt to save mutated settings
                AppSettingsData mutated = new AppSettingsData();
                mutated.ThemePreference = "UnsavedMutatedTheme";
                mutated.LanguagePreference = "fr";
                string failErr;
                bool failedSaveResult = SettingsRepository.Save(mutated, out failErr);

                // 4. Verify cache did NOT advance and Load() returns the uncorrupted baseline
                AppSettingsData cachedAfter = SettingsRepository.Load();

                bool pass28A = baselineOk &&
                               (!failedSaveResult) &&
                               (!string.IsNullOrEmpty(failErr)) &&
                               (cachedAfter != null) &&
                               (cachedAfter.ThemePreference == "InitialBaselineTheme") &&
                               (cachedAfter.LanguagePreference == "en");

                SettingsRepository.FaultInjectionSaveSeam = null;

                if (!pass28A)
                {
                    failures.Add(string.Format("Test 28A Failed: Save failure allowed cache advance or corrupt state. baselineOk={0}, failedSave={1}, err={2}, theme={3}",
                        baselineOk, failedSaveResult, failErr, cachedAfter != null ? cachedAfter.ThemePreference : "null"));
                    log("  FAILED: Settings cache advanced despite persistence failure or failed to preserve baseline.");
                }
                else
                {
                    log("  PASSED: Cache isolation verified: write failure blocked cache advance and preserved acknowledged baseline.");
                }

                // ── TEST 28B: Missing Primary File Recovers from Backup ──
                log("[Test 28B] Missing Primary File with Valid Backup Fallback...");
                SettingsRepository.ResetCache();

                string settingsJsonPath = SettingsRepository.GetFilePath();
                string settingsBakPath = SettingsRepository.GetBackupFilePath();

                AppSettingsData backupSettings = new AppSettingsData();
                backupSettings.ThemePreference = "RecoveredFromBackupTheme";
                backupSettings.AutoLockOnStartup = true;
                string bakJson = serializer.Serialize(backupSettings);

                // Write only backup file, ensure primary file is missing
                try { if (File.Exists(settingsJsonPath)) File.Delete(settingsJsonPath); } catch { }
                File.WriteAllText(settingsBakPath, bakJson);

                AppSettingsData loadedFromBak = SettingsRepository.Load();
                bool pass28B = loadedFromBak != null &&
                               loadedFromBak.ThemePreference == "RecoveredFromBackupTheme" &&
                               loadedFromBak.AutoLockOnStartup == true;

                if (!pass28B)
                {
                    failures.Add(string.Format("Test 28B Failed: Missing primary file failed to recover from settings.bak. loaded={0}, theme={1}",
                        loadedFromBak != null, loadedFromBak != null ? loadedFromBak.ThemePreference : "null"));
                    log("  FAILED: Settings repository did not recover from valid settings.bak when primary was missing.");
                }
                else
                {
                    log("  PASSED: Automatic recovery from settings.bak verified when primary settings file is absent.");
                }

                // ── TEST 28C: Corrupted Primary File Recovers from Backup ──
                log("[Test 28C] Corrupted Primary File Fallback to Valid Backup...");
                SettingsRepository.ResetCache();

                // Write corrupted garbage to primary file
                File.WriteAllText(settingsJsonPath, "{ CORRUPTED_SETTINGS_JSON_TRUNCATED: true ");

                AppSettingsData loadedAfterCorrupt = SettingsRepository.Load();
                bool pass28C = loadedAfterCorrupt != null &&
                               loadedAfterCorrupt.ThemePreference == "RecoveredFromBackupTheme" &&
                               loadedAfterCorrupt.AutoLockOnStartup == true;

                if (!pass28C)
                {
                    failures.Add(string.Format("Test 28C Failed: Corrupted primary file did not cleanly recover from settings.bak. theme={0}",
                        loadedAfterCorrupt != null ? loadedAfterCorrupt.ThemePreference : "null"));
                    log("  FAILED: Corrupted settings file failed to fall back to settings.bak.");
                }
                else
                {
                    log("  PASSED: Corrupted primary settings file cleanly fell back to valid settings.bak.");
                }

                // ── TEST 28D: Successful Save Creates/Updates Backup & Commits Cache ──
                log("[Test 28D] Atomic Replacement & Backup Creation Verification...");
                SettingsRepository.ResetCache();

                AppSettingsData v1 = new AppSettingsData();
                v1.ThemePreference = "Version1Theme";
                string errV1;
                bool saveV1Ok = SettingsRepository.Save(v1, out errV1);

                AppSettingsData v2 = new AppSettingsData();
                v2.ThemePreference = "Version2Theme";
                string errV2;
                bool saveV2Ok = SettingsRepository.Save(v2, out errV2);

                // Both files should exist: primary should have v2, backup should have v1
                bool primaryExists = File.Exists(settingsJsonPath);
                bool backupExists = File.Exists(settingsBakPath);

                string primaryContent = primaryExists ? File.ReadAllText(settingsJsonPath) : "";
                string backupContent = backupExists ? File.ReadAllText(settingsBakPath) : "";

                AppSettingsData primaryData = serializer.Deserialize<AppSettingsData>(primaryContent);
                AppSettingsData backupData = serializer.Deserialize<AppSettingsData>(backupContent);

                AppSettingsData loadedActive = SettingsRepository.Load();

                bool pass28D = saveV1Ok && saveV2Ok &&
                               primaryExists && backupExists &&
                               primaryData != null && primaryData.ThemePreference == "Version2Theme" &&
                               backupData != null && backupData.ThemePreference == "Version1Theme" &&
                               loadedActive != null && loadedActive.ThemePreference == "Version2Theme";

                if (!pass28D)
                {
                    failures.Add(string.Format("Test 28D Failed: Atomic replace/backup creation failed. v1Ok={0}, v2Ok={1}, pExists={2}, bExists={3}, pTheme={4}, bTheme={5}",
                        saveV1Ok, saveV2Ok, primaryExists, backupExists,
                        primaryData != null ? primaryData.ThemePreference : "null",
                        backupData != null ? backupData.ThemePreference : "null"));
                    log("  FAILED: Atomic replace did not update primary or preserve previous state in backup.");
                }
                else
                {
                    log("  PASSED: Atomic save verified: primary updated to v2, backup safely preserved v1, cache matches primary.");
                }

                // ── TEST 28E: In-Memory Mutation Isolation (Cloning Invariant) ──
                log("[Test 28E] In-Memory Mutation Isolation (Cloning Invariant)...");
                SettingsRepository.ResetCache();

                // Load cached settings
                AppSettingsData retrieved = SettingsRepository.Load();
                string originalTheme = retrieved.ThemePreference;

                // Mutate the object reference without calling Save()
                retrieved.ThemePreference = "MutatedWithoutSaving";

                // Load again - cache must NOT have changed!
                AppSettingsData freshLoad = SettingsRepository.Load();

                bool pass28E = freshLoad != null &&
                               freshLoad.ThemePreference == originalTheme &&
                               freshLoad.ThemePreference != "MutatedWithoutSaving";

                if (!pass28E)
                {
                    failures.Add(string.Format("Test 28E Failed: Load() returned live reference allowing uncontrolled cache mutation. original={0}, mutated={1}, fresh={2}",
                        originalTheme, retrieved.ThemePreference, freshLoad != null ? freshLoad.ThemePreference : "null"));
                    log("  FAILED: Direct mutation of Load() object leaked into internal settings cache.");
                }
                else
                {
                    log("  PASSED: Load() returns isolated clone: direct mutation does not contaminate repository cache.");
                }
            }
            finally
            {
                DeviceEnforcementLifecycleManager.DisableTestMode();
                SecurityAclHelper.BaseDirectoryOverride = origOverride;
                SettingsRepository.FaultInjectionSaveSeam = null;
                SettingsRepository.FaultInjectionLoadSeam = null;
                SettingsRepository.ResetCache();
                try
                {
                    if (Directory.Exists(testDir)) Directory.Delete(testDir, true);
                }
                catch { }
            }
        }

        // ═══════════════════════════════════════════════════════════════════════════
        // TEST 29: v2.1 Phase 5.8 Authentication & Recovery File Integrity (LIFE-05)
        // ═══════════════════════════════════════════════════════════════════════════
        public static void RunPhase58Life05Tests(Action<string> log, List<string> failures)
        {
            if (log == null) log = delegate { };
            if (failures == null) failures = new List<string>();

            log("");
            log("================================================================================");
            log("  [Test 29] v2.1 Phase 5.8 Authentication & Recovery File Integrity (LIFE-05)");
            log("  Permanent Regression Suite for Atomic Replacement, Backup Preservation,");
            log("  Corrupted Verifier Fallback, and Fail-Closed Security Guards");
            log("================================================================================");

            string testDir = Path.Combine(Path.GetTempPath(), "UsbShield_Test29_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(testDir);
            string origOverride = SecurityAclHelper.BaseDirectoryOverride;
            SecurityAclHelper.BaseDirectoryOverride = testDir;

            try
            {
                DeviceEnforcementLifecycleManager.EnableTestMode();
                // ── TEST 29A: Password Replacement Failure Preserves Prior Valid Password ──
                log("[Test 29A] Password Change Failure Gating: Prior Password Preserved on Write Failure...");
                PasswordManager.RemovePassword();

                // 1. Set initial known password
                string setErr1;
                bool initialOk = PasswordManager.SetPassword("InitialMasterPassword123!", out setErr1);
                bool initialVerify = PasswordManager.VerifyPassword("InitialMasterPassword123!");

                // 2. Inject failure seam to simulate write failure / disk full / access denied
                PasswordManager.FaultInjectionSaveSeam = delegate(string pw)
                {
                    return "Simulated Disk Full During Password Rotation";
                };

                // 3. Attempt to update password to a new value
                string setErr2;
                bool rotationResult = PasswordManager.SetPassword("NewAttemptedPassword999!", out setErr2);

                PasswordManager.FaultInjectionSaveSeam = null;

                // 4. Verify rotation failed cleanly, previous password is still intact, and new password is NOT accepted
                bool oldStillValid = PasswordManager.VerifyPassword("InitialMasterPassword123!");
                bool newNotAccepted = !PasswordManager.VerifyPassword("NewAttemptedPassword999!");

                bool pass29A = initialOk && initialVerify && (!rotationResult) &&
                               (!string.IsNullOrEmpty(setErr2)) && oldStillValid && newNotAccepted;

                if (!pass29A)
                {
                    failures.Add(string.Format("Test 29A Failed: Password change failure did not preserve prior password. initOk={0}, initV={1}, rot={2}, err={3}, oldV={4}, newV={5}",
                        initialOk, initialVerify, rotationResult, setErr2, oldStillValid, !newNotAccepted));
                    log("  FAILED: Password replacement failure destroyed or altered previous valid password.");
                }
                else
                {
                    log("  PASSED: Password replacement failure safely preserved prior valid password and rejected uncommitted credential.");
                }

                // ── TEST 29B: Corrupted Primary .auth File Recovers from .auth.bak ──
                log("[Test 29B] Corrupted Primary .auth Fallback to Backup Verifier...");
                // Rotate password legitimately so .auth has v2 and .auth.bak has v1
                string setErr3;
                bool secondOk = PasswordManager.SetPassword("SecondRotatedPassword456!", out setErr3);
                bool secondVerify = PasswordManager.VerifyPassword("SecondRotatedPassword456!");

                string authPath = PasswordManager.GetAuthFilePath();
                string authBak = PasswordManager.GetAuthBackupFilePath();
                bool authExists = File.Exists(authPath);
                bool authBakExists = File.Exists(authBak);

                // Overwrite primary .auth with corrupt garbage bytes
                try { File.SetAttributes(authPath, FileAttributes.Normal); } catch { }
                File.WriteAllBytes(authPath, new byte[] { 0xDE, 0xAD, 0xBE, 0xEF, 0x00, 0x01, 0x02 });

                // Verification of backup password should succeed via .auth.bak fallback
                bool bakFallbackOk = PasswordManager.VerifyPassword("InitialMasterPassword123!");

                bool pass29B = secondOk && secondVerify && authExists && authBakExists && bakFallbackOk;

                if (!pass29B)
                {
                    failures.Add(string.Format("Test 29B Failed: Corrupted primary .auth did not fall back to .auth.bak. secOk={0}, secV={1}, pEx={2}, bEx={3}, bakFallback={4}",
                        secondOk, secondVerify, authExists, authBakExists, bakFallbackOk));
                    log("  FAILED: Corrupted primary auth verifier failed to fall back to valid backup verifier.");
                }
                else
                {
                    log("  PASSED: Corrupted primary auth verifier cleanly fell back to valid .auth.bak and authenticated user.");
                }

                // ── TEST 29C: Recovery Verifier Replacement Failure Preserves Prior Key ──
                log("[Test 29C] Master Recovery Key Rotation Failure: Prior Key Preserved on Write Failure...");
                RecoveryKeyManager.DeleteMasterRecoveryKey();

                string key1 = RecoveryKeyManager.GenerateKeyString();
                string saveKeyErr1;
                bool key1Ok = RecoveryKeyManager.SaveMasterRecoveryKey(key1, out saveKeyErr1);
                bool key1Verify = RecoveryKeyManager.VerifyMasterRecoveryKey(key1);

                // Inject failure seam into RecoveryKeyManager
                RecoveryKeyManager.FaultInjectionSaveSeam = delegate(string k)
                {
                    return "Simulated Access Denied on Key Rotation";
                };

                string key2 = RecoveryKeyManager.GenerateKeyString();
                string saveKeyErr2;
                bool key2Ok = RecoveryKeyManager.SaveMasterRecoveryKey(key2, out saveKeyErr2);

                RecoveryKeyManager.FaultInjectionSaveSeam = null;

                bool key1StillValid = RecoveryKeyManager.VerifyMasterRecoveryKey(key1);
                bool key2NotAccepted = !RecoveryKeyManager.VerifyMasterRecoveryKey(key2);

                bool pass29C = key1Ok && key1Verify && (!key2Ok) &&
                               (!string.IsNullOrEmpty(saveKeyErr2)) && key1StillValid && key2NotAccepted;

                if (!pass29C)
                {
                    failures.Add(string.Format("Test 29C Failed: Recovery key rotation failure did not preserve prior key. k1Ok={0}, k1V={1}, k2Ok={2}, err={3}, k1Valid={4}, k2Acc={5}",
                        key1Ok, key1Verify, key2Ok, saveKeyErr2, key1StillValid, !key2NotAccepted));
                    log("  FAILED: Recovery verifier rotation failure destroyed or altered previous valid key.");
                }
                else
                {
                    log("  PASSED: Recovery verifier rotation failure safely preserved prior valid key and rejected uncommitted key.");
                }

                // ── TEST 29D: Corrupted Primary .recovery File Recovers from .recovery.bak ──
                log("[Test 29D] Corrupted Primary .recovery Fallback to Backup Verifier...");
                // Rotate recovery key legitimately so .recovery has key2 and .recovery.bak has key1
                string key3 = RecoveryKeyManager.GenerateKeyString();
                string saveKeyErr3;
                bool key3Ok = RecoveryKeyManager.SaveMasterRecoveryKey(key3, out saveKeyErr3);
                bool key3Verify = RecoveryKeyManager.VerifyMasterRecoveryKey(key3);

                string recPath = RecoveryKeyManager.GetRecoveryFilePath();
                string recBak = RecoveryKeyManager.GetRecoveryBackupFilePath();
                bool recExists = File.Exists(recPath);
                bool recBakExists = File.Exists(recBak);

                // Overwrite primary .recovery with corrupt garbage bytes
                try { File.SetAttributes(recPath, FileAttributes.Normal); } catch { }
                File.WriteAllBytes(recPath, new byte[] { 0xCA, 0xFE, 0xBA, 0xBE, 0x99, 0x88 });

                // Verification of backup recovery key should succeed via .recovery.bak fallback
                bool recBakFallbackOk = RecoveryKeyManager.VerifyMasterRecoveryKey(key1);

                bool pass29D = key3Ok && key3Verify && recExists && recBakExists && recBakFallbackOk;

                if (!pass29D)
                {
                    failures.Add(string.Format("Test 29D Failed: Corrupted primary .recovery did not fall back to .recovery.bak. k3Ok={0}, k3V={1}, rEx={2}, bEx={3}, fallback={4}",
                        key3Ok, key3Verify, recExists, recBakExists, recBakFallbackOk));
                    log("  FAILED: Corrupted primary recovery verifier failed to fall back to valid backup verifier.");
                }
                else
                {
                    log("  PASSED: Corrupted primary recovery verifier cleanly fell back to valid .recovery.bak and verified key.");
                }

                // ── TEST 29E: Fail-Closed Security Invariant: Corrupted State Reports Configured (No Bypass) ──
                log("[Test 29E] Fail-Closed Security Invariant: Unreadable/Corrupted Auth Reports IsConfigured=true...");
                // When auth file exists on disk (even if corrupted or standard-user unreadable),
                // IsPasswordConfigured() MUST return true so authentication guards do NOT fail-open.
                try { File.SetAttributes(authPath, FileAttributes.Normal); } catch { }
                File.WriteAllBytes(authPath, new byte[] { 0x01, 0x02, 0x03 });
                bool configuredOnCorrupt = PasswordManager.IsPasswordConfigured();

                // Delete primary, but leave non-empty backup
                try { File.SetAttributes(authPath, FileAttributes.Normal); File.Delete(authPath); } catch { }
                try { File.SetAttributes(authBak, FileAttributes.Normal); } catch { }
                File.WriteAllBytes(authBak, new byte[] { 0x04, 0x05, 0x06 });
                bool configuredOnBakOnly = PasswordManager.IsPasswordConfigured();

                bool pass29E = configuredOnCorrupt && configuredOnBakOnly;

                if (!pass29E)
                {
                    failures.Add(string.Format("Test 29E Failed: Fail-closed invariant violated. corruptConfigured={0}, bakOnlyConfigured={1}",
                        configuredOnCorrupt, configuredOnBakOnly));
                    log("  FAILED: Fail-closed guard returned false for existing auth artifacts, enabling authentication bypass.");
                }
                else
                {
                    log("  PASSED: Fail-closed security invariant verified: non-empty auth/backup artifacts report configured, preventing fail-open bypass.");
                }

                // ── TEST 29F: Authorized Credential Removal Cleans All Verifiers ──
                log("[Test 29F] Authorized Removal Cleans All Primary and Backup Artifacts...");
                bool removePwOk = PasswordManager.RemovePassword();
                bool removeKeyOk = RecoveryKeyManager.DeleteMasterRecoveryKey();

                bool authClean = !File.Exists(authPath) && !File.Exists(authBak) && !PasswordManager.IsPasswordConfigured();
                bool recClean = !File.Exists(recPath) && !File.Exists(recBak) && !RecoveryKeyManager.IsRecoveryKeyConfigured();

                bool pass29F = removePwOk && removeKeyOk && authClean && recClean;

                if (!pass29F)
                {
                    failures.Add(string.Format("Test 29F Failed: Credential removal did not clean all artifacts. rmPw={0}, rmKey={1}, authClean={2}, recClean={3}",
                        removePwOk, removeKeyOk, authClean, recClean));
                    log("  FAILED: Authorized credential removal left residual primary or backup verifiers.");
                }
                else
                {
                    log("  PASSED: Authorized credential removal completely erased primary and backup artifacts with zero residual verifiers.");
                }
            }
            finally
            {
                DeviceEnforcementLifecycleManager.DisableTestMode();
                SecurityAclHelper.BaseDirectoryOverride = origOverride;
                PasswordManager.FaultInjectionSaveSeam = null;
                RecoveryKeyManager.FaultInjectionSaveSeam = null;
                try
                {
                    if (Directory.Exists(testDir)) Directory.Delete(testDir, true);
                }
                catch { }
            }
        }

        public static void RunPhase59DeviceEnforcementTests(Action<string> log, List<string> failures)
        {
            if (log == null) log = delegate { };
            if (failures == null) failures = new List<string>();

            log("");
            log("================================================================================");
            log("  [Test 30] v2.1 Phase 5.9 Core USB Enforcement, Device Identity & Safety (SEC-03..06)");
            log("  Permanent Regression Suite for Whitelist vs Class Policy Precedence,");
            log("  UASP / SCSI USB Topology Classification, In-Flight Worker Cancellation,");
            log("  System Disk & Boot Guard Boundaries, and Read-Only Policy Reconcile");
            log("================================================================================");

            string testDir = Path.Combine(Path.GetTempPath(), "UsbShield_Test30_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(testDir);
            string origOverride = SecurityAclHelper.BaseDirectoryOverride;
            SecurityAclHelper.BaseDirectoryOverride = testDir;
            DeviceEnforcementLifecycleManager.EnableTestMode();

            try
            {
                // ── TEST 30A: Class-Wide Removable Storage Policy Overrides Trusted Device Whitelist (SEC-04) ──
                log("[Test 30A] Class-Wide Policy Precedence: BlockAll / BlockRemovableDisks Overrides Trusted Whitelist...");
                DeviceIdentity dev30A = new DeviceIdentity
                {
                    FriendlyName = "Kingston DataTraveler 30A",
                    SerialNumber = "DT100G3_SERIAL_30A",
                    PhysicalUsbParentInstanceId = @"USB\VID_0951&PID_1666\DT100G3_SERIAL_30A",
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_KINGSTON&PROD_DATATRAVELER_3.0\DT100G3_SERIAL_30A&0",
                    PhysicalDiskNumber = 1,
                    PhysicalTransport = PhysicalBusType.Usb,
                    WindowsClass = StorageClass.DiskDrive,
                    Category = DeviceCategory.UsbFlashDrive,
                    IsRemovableMedia = true,
                    SafetyResult = SafetyValidationResult.Passed
                };

                // Configure device as trusted in repository seam
                TrustedDeviceRepository.IsDeviceTrustedSeam = delegate(DeviceIdentity d) { return true; };

                // 1. Policy with BlockAllRemovable = true
                ProtectionPolicy policyBlockAll = new ProtectionPolicy { BlockAllRemovable = true, WhitelistMode = false };
                var evalBlockAll = RuleEngine.Evaluate(dev30A, policyBlockAll, false);
                bool ejectReqBlockAll = ActiveSentinel.IsAutoEjectRequired(dev30A, policyBlockAll);

                // 2. Policy with BlockRemovableDisks = true
                ProtectionPolicy policyBlockDisks = new ProtectionPolicy { BlockRemovableDisks = true, WhitelistMode = false };
                var evalBlockDisks = RuleEngine.Evaluate(dev30A, policyBlockDisks, false);
                bool ejectReqBlockDisks = ActiveSentinel.IsAutoEjectRequired(dev30A, policyBlockDisks);

                bool pass30A = (evalBlockAll.RecommendedAction == RuleAction.DenyBlocked) &&
                               (evalBlockAll.DisplayBadge == "CLASS BLOCKED (TRUST OVERRIDDEN)") &&
                               (evalBlockAll.ShouldAutoEject == true) &&
                               ejectReqBlockAll &&
                               (evalBlockDisks.RecommendedAction == RuleAction.DenyBlocked) &&
                               (evalBlockDisks.DisplayBadge == "CLASS BLOCKED (TRUST OVERRIDDEN)") &&
                               (evalBlockDisks.ShouldAutoEject == true) &&
                               ejectReqBlockDisks;

                if (!pass30A)
                {
                    failures.Add(string.Format("Test 30A Failed: Class policy did not supersede whitelist. BlockAll: act={0}, badge={1}, ej={2}; BlockDisks: act={3}, badge={4}, ej={5}",
                        evalBlockAll.RecommendedAction, evalBlockAll.DisplayBadge, evalBlockAll.ShouldAutoEject,
                        evalBlockDisks.RecommendedAction, evalBlockDisks.DisplayBadge, evalBlockDisks.ShouldAutoEject));
                    log("  FAILED: Trusted device incorrectly exempted from class-wide Removable Storage policy.");
                }
                else
                {
                    log("  PASSED: Class-wide blocking policies (BlockAll / BlockRemovableDisks) authoritatively supersede trusted whitelist.");
                }

                // ── TEST 30B: Authorized Whitelist Device Permitted under Whitelist Mode (SEC-04) ──
                log("[Test 30B] Authorized Whitelist Match: Permitted under Whitelist-Only Mode without Auto-Ejection...");
                ProtectionPolicy policyWhitelist = new ProtectionPolicy { WhitelistMode = true, BlockAllRemovable = false, BlockRemovableDisks = false };
                var evalWhitelist = RuleEngine.Evaluate(dev30A, policyWhitelist, false);
                bool ejectReqWhitelist = ActiveSentinel.IsAutoEjectRequired(dev30A, policyWhitelist);

                bool pass30B = (evalWhitelist.RecommendedAction == RuleAction.AllowTrusted) &&
                               (evalWhitelist.DisplayBadge == "TRUSTED") &&
                               (evalWhitelist.ShouldAutoEject == false) &&
                               (!ejectReqWhitelist);

                if (!pass30B)
                {
                    failures.Add(string.Format("Test 30B Failed: Whitelist mode rejected or auto-ejected authorized trusted device. act={0}, badge={1}, ej={2}",
                        evalWhitelist.RecommendedAction, evalWhitelist.DisplayBadge, evalWhitelist.ShouldAutoEject));
                    log("  FAILED: Authorized trusted device was incorrectly blocked or ejected in Whitelist mode.");
                }
                else
                {
                    log("  PASSED: Authorized trusted device correctly permitted without auto-ejection under Whitelist Mode.");
                }

                // ── TEST 30C: UASP / SCSI-Reported USB Storage Device Classification (SEC-03) ──
                log("[Test 30C] UASP / SCSI-Reported USB Storage: Accurate USB Ancestry Resolution & Safety Validation...");
                DeviceIdentity devUasp = new DeviceIdentity
                {
                    FriendlyName = "ASMT 2115 UASP External SSD",
                    Model = "ASMT 2115",
                    DeviceInstanceId = @"SCSI\DISK&VEN_ASMEDIA&PROD_2115\000000",
                    PhysicalUsbParentInstanceId = @"USB\VID_174C&PID_55AA\1234567890AB",
                    ImmediateParentInstanceId = @"UASPSTOR\DISK&VEN_ASMEDIA&PROD_2115\0",
                    SerialNumber = "1234567890AB",
                    PhysicalDiskNumber = 2,
                    PartitionCount = 1,
                    PhysicalTransport = PhysicalBusType.Usb,
                    WindowsClass = StorageClass.DiskDrive,
                    SetupClassGuid = "{4d36e967-e325-11ce-bfc1-08002be10318}",
                    IsRemovableMedia = false,
                    HasSeekPenalty = false,
                    TotalSizeBytes = 512110190592L,
                    VolumeMountings = new List<string> { "T:" }
                };

                DeviceCategory uaspCat = DeviceClassifier.Classify(devUasp);
                string uaspSafetyReason;
                SafetyValidationResult uaspSafety = SystemDeviceSafetyGuard.ValidateDevice(devUasp, out uaspSafetyReason);
                bool uaspPnpSupported = PnpSafeEjectBackend.IsSupported(devUasp);

                bool pass30C = (devUasp.PhysicalTransport == PhysicalBusType.Usb) &&
                               (uaspCat == DeviceCategory.ExternalUsbSsd) &&
                               (uaspSafety == SafetyValidationResult.Passed) &&
                               uaspPnpSupported;

                if (!pass30C)
                {
                    failures.Add(string.Format("Test 30C Failed: UASP drive classification failed. Transport={0}, Cat={1}, Safety={2} ({3}), PnpSupported={4}",
                        devUasp.PhysicalTransport, uaspCat, uaspSafety, uaspSafetyReason, uaspPnpSupported));
                    log("  FAILED: UASP / SCSI-reported USB storage was not recognized as removable/ejectable USB storage.");
                }
                else
                {
                    log("  PASSED: UASP / SCSI-reported storage correctly classified as ExternalUsbSsd, passed safety guard, and accepted for PnP ejection.");
                }

                // ── TEST 30D: Strict Internal System & Boot Disk Exclusion Boundaries (SEC-03, SEC-08) ──
                log("[Test 30D] System Disk Safety Boundaries: Disk 0, Boot Volume & Internal Controllers Strictly Protected...");
                SystemDeviceSafetyGuard.SystemPhysicalDiskNumberSeam = 0;

                DeviceIdentity devDisk0 = new DeviceIdentity
                {
                    FriendlyName = "Internal Boot NVMe SSD (Disk 0)",
                    DeviceInstanceId = @"NVME\DISK&VEN_SAMSUNG&PROD_980_PRO\0",
                    PhysicalDiskNumber = 0,
                    PhysicalTransport = PhysicalBusType.Nvme,
                    WindowsClass = StorageClass.DiskDrive,
                    SetupClassGuid = "{4d36e967-e325-11ce-bfc1-08002be10318}",
                    VolumeMountings = new List<string> { "C:" }
                };

                string safetyReasonDisk0;
                SafetyValidationResult safetyDisk0 = SystemDeviceSafetyGuard.ValidateDevice(devDisk0, out safetyReasonDisk0);
                var evalDisk0 = RuleEngine.Evaluate(devDisk0, policyBlockAll, false);
                bool pnpSupportedDisk0 = PnpSafeEjectBackend.IsSupported(devDisk0);

                // Spoofed USB transport on Disk 0 must still be strictly protected
                DeviceIdentity devSpoofedUsbDisk0 = new DeviceIdentity
                {
                    FriendlyName = "Spoofed USB Disk 0",
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_SPOOFED&PROD_DISK\000000",
                    PhysicalUsbParentInstanceId = @"USB\VID_1234&PID_5678\000000",
                    PhysicalDiskNumber = 0,
                    PhysicalTransport = PhysicalBusType.Usb,
                    WindowsClass = StorageClass.DiskDrive,
                    SetupClassGuid = "{4d36e967-e325-11ce-bfc1-08002be10318}",
                    IsRemovableMedia = true,
                    VolumeMountings = new List<string> { "C:" }
                };

                string safetyReasonSpoofed;
                SafetyValidationResult safetySpoofed = SystemDeviceSafetyGuard.ValidateDevice(devSpoofedUsbDisk0, out safetyReasonSpoofed);
                bool pnpSupportedSpoofed = PnpSafeEjectBackend.IsSupported(devSpoofedUsbDisk0);

                bool pass30D = (safetyDisk0 == SafetyValidationResult.RejectedSystemOrBootDisk) &&
                               (evalDisk0.IsSafetyProtected == true) &&
                               (!evalDisk0.ShouldAutoEject) &&
                               (!pnpSupportedDisk0) &&
                               (safetySpoofed == SafetyValidationResult.RejectedSystemOrBootDisk) &&
                               (!pnpSupportedSpoofed);

                if (!pass30D)
                {
                    failures.Add(string.Format("Test 30D Failed: Internal system disk boundary breached. Disk0: safety={0}, protected={1}, pnp={2}; Spoofed: safety={3}, pnp={4}",
                        safetyDisk0, evalDisk0.IsSafetyProtected, pnpSupportedDisk0, safetySpoofed, pnpSupportedSpoofed));
                    log("  FAILED: System disk 0 or boot drive was not strictly protected by SystemDeviceSafetyGuard.");
                }
                else
                {
                    log("  PASSED: System disk 0 and active boot volumes unconditionally protected against ejection, even when transport flags are spoofed.");
                }

                // ── TEST 30E: In-Flight Worker Cancellation & Temporary Access Activation (SEC-06) ──
                log("[Test 30E] Temporary Access Worker Abatement: In-Flight Ejection Workers Cancelled Immediately...");
                DeviceEnforcementLifecycleManager.ResetForTest();
                string physicalKey30E = DeviceEnforcementLifecycleManager.BuildPhysicalKey(dev30A);
                DeviceLifecycleRecord rec30E;
                bool startEnfOk = DeviceEnforcementLifecycleManager.TryStartEnforcement(dev30A, out rec30E);
                CancellationTokenSource testCts = new CancellationTokenSource();
                if (rec30E != null)
                {
                    rec30E.ActiveCts = testCts;
                }

                // Verify worker is active before temporary access
                var snapBefore = DeviceEnforcementLifecycleManager.GetLifecycleSnapshot(physicalKey30E);
                bool beforeOk = startEnfOk && (snapBefore != null && snapBefore.State == EnforcementState.Evaluating && !testCts.IsCancellationRequested);

                // Activate Temporary Access
                TemporaryAccessManager.PolicyApplier = delegate(ProtectionPolicy p) { return new List<string>(); };
                string tempErr30E;
                bool tempStartOk = TemporaryAccessManager.StartTemporaryAccess(15, policyBlockAll, out tempErr30E);

                var snapAfter = DeviceEnforcementLifecycleManager.GetLifecycleSnapshot(physicalKey30E);
                bool ctsCancelled = testCts.IsCancellationRequested;
                bool tempActive = TemporaryAccessManager.IsActive;
                bool ejectSuppressed = !ActiveSentinel.IsAutoEjectRequired(dev30A, policyBlockAll);
                var evalTemp = RuleEngine.Evaluate(dev30A, policyBlockAll, TemporaryAccessManager.IsActive);

                bool pass30E = beforeOk && tempStartOk && ctsCancelled &&
                               (snapAfter != null && snapAfter.State == EnforcementState.SuspendedPolicyOff) &&
                               tempActive && ejectSuppressed &&
                               (evalTemp.RecommendedAction == RuleAction.AllowTrusted) &&
                               (evalTemp.DisplayBadge == "TEMP ALLOWED") &&
                               (!evalTemp.ShouldAutoEject);

                if (!pass30E)
                {
                    failures.Add(string.Format("Test 30E Failed: Temporary access did not cancel in-flight workers. before={0}, start={1}, err={2}, ctsCanceled={3}, stateAfter={4}, tempAct={5}, ejectSupp={6}, evalBadge={7}",
                        beforeOk, tempStartOk, tempErr30E, ctsCancelled, snapAfter != null ? snapAfter.State.ToString() : "NULL", tempActive, ejectSuppressed, evalTemp.DisplayBadge));
                    log("  FAILED: Temporary access failed to cancel in-flight enforcement worker or suppress auto-ejection.");
                }
                else
                {
                    log("  PASSED: Temporary access activation immediately cancelled in-flight workers, abated retry loops, and suppressed auto-ejection.");
                }

                // ── TEST 30F: Read-Only Policy Transition Clears Lingering Deny_Read (SEC-05) ──
                log("[Test 30F] Read-Only Policy Transition: Lingering Deny_Read Value Deleted from Registry...");
                RegistryTransactionHelper.HiveOverride = RegistryHive.CurrentUser;
                RegistryTransactionHelper.KeyPathRewriter = delegate(string p) { return @"SOFTWARE\USBShieldPro\TestHarness\" + p.Replace('\\', '_'); };
                try
                {
                    string rsKeyPath = WindowsSecurityConstants.RemovableStoragePoliciesPath + "\\" + WindowsSecurityConstants.GuidRemovableDisks;

                    // 1. Simulate prior BlockRemovableDisks by setting Deny_Read=1 and Deny_Write=1
                    string initBlockErr;
                    bool setBlockedOk = RemovableStoragePolicyBackend.SetRemovableDiskPolicy(true, true, out initBlockErr);

                    // 2. Transition to Read-Only Mode
                    string roErr;
                    bool setRoOk = RemovableStoragePolicyBackend.SetReadOnlyMode(true, out roErr);

                    // 3. Inspect Registry state
                    bool denyReadPresent = false;
                    int denyWriteVal = -1;
                    int writeProtectVal = -1;

                    using (var baseKey = RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64))
                    {
                        string rwPath = RegistryTransactionHelper.KeyPathRewriter != null ? RegistryTransactionHelper.KeyPathRewriter(rsKeyPath) : rsKeyPath;
                        using (var subKey = baseKey.OpenSubKey(rwPath, false))
                        {
                            if (subKey != null)
                            {
                                object rVal = subKey.GetValue(WindowsSecurityConstants.ValueDenyRead);
                                if (rVal != null) denyReadPresent = true;

                                object wVal = subKey.GetValue(WindowsSecurityConstants.ValueDenyWrite);
                                if (wVal is int) denyWriteVal = (int)wVal;
                            }
                        }

                        string spPath = RegistryTransactionHelper.KeyPathRewriter != null ? RegistryTransactionHelper.KeyPathRewriter(WindowsSecurityConstants.StorageDevicePoliciesPath) : WindowsSecurityConstants.StorageDevicePoliciesPath;
                        using (var subKey = baseKey.OpenSubKey(spPath, false))
                        {
                            if (subKey != null)
                            {
                                object wpVal = subKey.GetValue(WindowsSecurityConstants.ValueWriteProtect);
                                if (wpVal is int) writeProtectVal = (int)wpVal;
                            }
                        }
                    }

                    bool pass30F = setBlockedOk && setRoOk && (!denyReadPresent) && (denyWriteVal == 1) && (writeProtectVal == 1);

                    if (!pass30F)
                    {
                        failures.Add(string.Format("Test 30F Failed: Read-Only transition did not clear Deny_Read. blockedOk={0}, roOk={1}, err={2}, denyReadPresent={3}, denyWrite={4}, writeProtect={5}",
                            setBlockedOk, setRoOk, roErr, denyReadPresent, denyWriteVal, writeProtectVal));
                        log("  FAILED: Transitioning to Read-Only mode left Deny_Read active, preventing read access.");
                    }
                    else
                    {
                        log("  PASSED: Transition to Read-Only mode cleanly deleted lingering Deny_Read while asserting Deny_Write and WriteProtect.");
                    }
                }
                finally
                {
                    try
                    {
                        using (var baseKey = RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64))
                        {
                            baseKey.DeleteSubKeyTree(@"SOFTWARE\USBShieldPro\TestHarness", false);
                        }
                    }
                    catch { }
                    RegistryTransactionHelper.KeyPathRewriter = null;
                    RegistryTransactionHelper.HiveOverride = null;
                }
            }
            finally
            {
                SecurityAclHelper.BaseDirectoryOverride = origOverride;
                DeviceEnforcementLifecycleManager.DisableTestMode();
                SystemDeviceSafetyGuard.ResetForTest();
                TrustedDeviceRepository.IsDeviceTrustedSeam = null;
                TemporaryAccessManager.PolicyApplier = null;
                TemporaryAccessManager.ResetCache();
                RegistryTransactionHelper.KeyPathRewriter = null;
                RegistryTransactionHelper.HiveOverride = null;
                try
                {
                    if (Directory.Exists(testDir)) Directory.Delete(testDir, true);
                }
                catch { }
            }
        }

        public static void RunPhase60EnforcementReadinessTests(Action<string> log, List<string> failures)
        {
            log("");
            log("================================================================================");
            log("  [Test 31] v2.1 Phase 6.0 Real Enforcement Readiness & SEC-02/SEC-08/SEC-09 Suite");
            log("  Permanent Regression Suite for Multi-Disk & Pagefile Safety Guard Hardening,");
            log("  Device Installation Allow-List Enable DWORDs, and Post-Verification Integrity");
            log("================================================================================");

            DeviceEnforcementLifecycleManager.IsTestMode = true;
            DeviceEnforcementLifecycleManager.ResetForTest();
            PnpSafeEjectBackend.ResetSeams();
            SystemDeviceSafetyGuard.ResetForTest();

            try
            {
                // ── TEST 31A: Multi-Disk System Safety Floor & Active Paging File Volumes (SEC-08) ──
                log("[Test 31A] Multi-Disk Safety Floor: Disk 0, Non-Zero OS Disk & Paging File Volumes Strictly Protected...");
                SystemDeviceSafetyGuard.SystemPhysicalDiskNumberSeam = 1; // Windows is on Disk 1
                SystemDeviceSafetyGuard.ActivePagingFileVolumesSeam = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "D:" };

                // 1. Disk 0 (bootloader/fallback) must be rejected even when Windows is on Disk 1
                DeviceIdentity devDisk0 = new DeviceIdentity
                {
                    FriendlyName = "Internal Bootloader Disk 0",
                    DeviceInstanceId = @"SCSI\DISK&VEN_SAMSUNG&PROD_SSD\0000",
                    PhysicalDiskNumber = 0,
                    PhysicalTransport = PhysicalBusType.Usb, // Even with spoofed USB transport!
                    WindowsClass = StorageClass.DiskDrive,
                    SetupClassGuid = "{4d36e967-e325-11ce-bfc1-08002be10318}"
                };
                string r0;
                var res0 = SystemDeviceSafetyGuard.ValidateDevice(devDisk0, out r0);

                // 2. Disk 1 (Windows System Drive) must be rejected
                DeviceIdentity devDisk1 = new DeviceIdentity
                {
                    FriendlyName = "OS Installation Disk 1",
                    DeviceInstanceId = @"SCSI\DISK&VEN_NVME&PROD_OS\0001",
                    PhysicalDiskNumber = 1,
                    PhysicalTransport = PhysicalBusType.Usb,
                    WindowsClass = StorageClass.DiskDrive,
                    SetupClassGuid = "{4d36e967-e325-11ce-bfc1-08002be10318}",
                    VolumeMountings = new List<string> { "C:" }
                };
                string r1;
                var res1 = SystemDeviceSafetyGuard.ValidateDevice(devDisk1, out r1);

                // 3. Disk 2 (USB Drive hosting active paging file on D:) must be rejected
                DeviceIdentity devDisk2 = new DeviceIdentity
                {
                    FriendlyName = "External Disk with Paging File (Disk 2)",
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_GENERIC&PROD_PAGEFILE\0002",
                    PhysicalDiskNumber = 2,
                    PhysicalTransport = PhysicalBusType.Usb,
                    WindowsClass = StorageClass.DiskDrive,
                    SetupClassGuid = "{4d36e967-e325-11ce-bfc1-08002be10318}",
                    VolumeMountings = new List<string> { "D:" }
                };
                string r2;
                var res2 = SystemDeviceSafetyGuard.ValidateDevice(devDisk2, out r2);

                // 4. Genuine external USB storage (Disk 3 with E:) must pass
                DeviceIdentity devDisk3 = new DeviceIdentity
                {
                    FriendlyName = "Genuine Removable USB Flash (Disk 3)",
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_SANDISK&PROD_ULTRA\0003",
                    PhysicalDiskNumber = 3,
                    PhysicalTransport = PhysicalBusType.Usb,
                    WindowsClass = StorageClass.DiskDrive,
                    SetupClassGuid = "{4d36e967-e325-11ce-bfc1-08002be10318}",
                    VolumeMountings = new List<string> { "E:" }
                };
                string r3;
                var res3 = SystemDeviceSafetyGuard.ValidateDevice(devDisk3, out r3);

                bool pass31A = (res0 == SafetyValidationResult.RejectedSystemOrBootDisk) &&
                               (res1 == SafetyValidationResult.RejectedSystemOrBootDisk) &&
                               (res2 == SafetyValidationResult.RejectedSystemOrBootDisk) &&
                               (r2 != null && r2.Contains("paging file")) &&
                               (res3 == SafetyValidationResult.Passed);

                if (!pass31A)
                {
                    failures.Add(string.Format("Test 31A Failed: Multi-disk safety failed. res0={0}, res1={1}, res2={2} (r2={3}), res3={4}",
                        res0, res1, res2, r2, res3));
                    log("  FAILED: Multi-disk safety guard did not protect Disk 0, non-zero OS disk, or paging file volume.");
                }
                else
                {
                    log("  PASSED: Disk 0 hard floor, non-zero OS disk (Disk 1), and active paging file volume (D:) unconditionally protected against ejection.");
                }

                // ── TEST 31B: Strict Device Installation Allow-List Enable DWORDs (SEC-02) ──
                log("[Test 31B] Device Installation Allow-Lists: Parent Enable DWORDs Asserted & Cleaned Up (SEC-02)...");
                RegistryTransactionHelper.HiveOverride = RegistryHive.CurrentUser;
                RegistryTransactionHelper.KeyPathRewriter = delegate(string p) { return @"SOFTWARE\USBShieldPro\TestHarness\" + p.Replace('\\', '_'); };
                try
                {
                    // 1. Add Device Instance ID
                    int idxInst;
                    string errInst;
                    bool addInstOk = DeviceInstallationPolicyBackend.AddAllowedDeviceInstanceId(@"USB\VID_1234&PID_5678\SN100", out idxInst, out errInst);

                    // Inspect that AllowInstanceIDs enable DWORD = 1 and subkey value "1" exists
                    int? enableInstVal = null;
                    string subkeyInstVal = null;
                    string restrKey = RegistryTransactionHelper.KeyPathRewriter(WindowsSecurityConstants.DeviceInstallRestrictionsPath);
                    string subkeyInstPath = RegistryTransactionHelper.KeyPathRewriter(WindowsSecurityConstants.DeviceInstallRestrictionsPath + "\\" + WindowsSecurityConstants.SubkeyAllowInstanceIDs);

                    using (var baseKey = RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64))
                    {
                        using (var subKey = baseKey.OpenSubKey(restrKey, false))
                        {
                            if (subKey != null)
                            {
                                object v = subKey.GetValue(WindowsSecurityConstants.ValueAllowInstanceIDs);
                                if (v is int) enableInstVal = (int)v;
                            }
                        }
                        using (var subKey = baseKey.OpenSubKey(subkeyInstPath, false))
                        {
                            if (subKey != null)
                            {
                                object v = subKey.GetValue(idxInst.ToString());
                                if (v != null) subkeyInstVal = v.ToString();
                            }
                        }
                    }

                    // 2. Remove Device Instance ID
                    string remErrInst;
                    bool remInstOk = DeviceInstallationPolicyBackend.RemoveAllowedDeviceInstanceId(idxInst, out remErrInst);

                    int? enableInstAfterRem = null;
                    using (var baseKey = RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64))
                    using (var subKey = baseKey.OpenSubKey(restrKey, false))
                    {
                        if (subKey != null)
                        {
                            object v = subKey.GetValue(WindowsSecurityConstants.ValueAllowInstanceIDs);
                            if (v is int) enableInstAfterRem = (int)v;
                        }
                    }

                    // 3. Add Hardware ID
                    int idxHw;
                    string errHw;
                    bool addHwOk = DeviceInstallationPolicyBackend.AddAllowedDeviceId(@"USB\VID_ABCD&PID_1234", out idxHw, out errHw);

                    int? enableHwVal = null;
                    string subkeyHwPath = RegistryTransactionHelper.KeyPathRewriter(WindowsSecurityConstants.DeviceInstallRestrictionsPath + "\\" + WindowsSecurityConstants.SubkeyAllowDeviceIDs);
                    using (var baseKey = RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64))
                    using (var subKey = baseKey.OpenSubKey(restrKey, false))
                    {
                        if (subKey != null)
                        {
                            object v = subKey.GetValue(WindowsSecurityConstants.ValueAllowDeviceIDs);
                            if (v is int) enableHwVal = (int)v;
                        }
                    }

                    // 4. Remove Hardware ID
                    string remErrHw;
                    bool remHwOk = DeviceInstallationPolicyBackend.RemoveAllowedDeviceId(idxHw, out remErrHw);

                    int? enableHwAfterRem = null;
                    using (var baseKey = RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64))
                    using (var subKey = baseKey.OpenSubKey(restrKey, false))
                    {
                        if (subKey != null)
                        {
                            object v = subKey.GetValue(WindowsSecurityConstants.ValueAllowDeviceIDs);
                            if (v is int) enableHwAfterRem = (int)v;
                        }
                    }

                    bool pass31B = addInstOk && (enableInstVal == 1) && (!string.IsNullOrEmpty(subkeyInstVal)) &&
                                   remInstOk && (!enableInstAfterRem.HasValue) &&
                                   addHwOk && (enableHwVal == 1) &&
                                   remHwOk && (!enableHwAfterRem.HasValue);

                    if (!pass31B)
                    {
                        failures.Add(string.Format("Test 31B Failed: Allow-list enable DWORD assertion failed. addInstOk={0}, enableInstVal={1}, subkeyInstVal={2}, remInstOk={3}, enableInstAfter={4}, addHwOk={5}, enableHwVal={6}, remHwOk={7}, enableHwAfter={8}",
                            addInstOk, enableInstVal, subkeyInstVal, remInstOk, enableInstAfterRem, addHwOk, enableHwVal, remHwOk, enableHwAfterRem));
                        log("  FAILED: Device installation allow-lists were written without parent enable DWORDs or failed clean removal.");
                    }
                    else
                    {
                        log("  PASSED: Device Installation allow-lists correctly assert parent enable DWORDs (AllowInstanceIDs=1, AllowDeviceIDs=1) and clean them up when empty.");
                    }
                }
                finally
                {
                    try
                    {
                        using (var baseKey = RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64))
                        {
                            baseKey.DeleteSubKeyTree(@"SOFTWARE\USBShieldPro\TestHarness", false);
                        }
                    }
                    catch { }
                    RegistryTransactionHelper.KeyPathRewriter = null;
                    RegistryTransactionHelper.HiveOverride = null;
                }

                // ── TEST 31C: PnP Safe-Eject Post-Verification Fails Closed on API Errors (SEC-09) ──
                log("[Test 31C] Post-Verification Integrity: Lookup Errors Fail Closed with VerificationIndeterminate (SEC-09)...");
                DeviceIdentity dev31C = new DeviceIdentity
                {
                    FriendlyName = "SanDisk 31C Eject Failure Test",
                    PhysicalUsbParentInstanceId = @"USB\VID_0781&PID_5583\SN31C",
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_SANDISK&PROD_ULTRA\SN31C",
                    PhysicalDiskNumber = 4,
                    PhysicalTransport = PhysicalBusType.Usb,
                    WindowsClass = StorageClass.DiskDrive,
                    SetupClassGuid = "{4d36e967-e325-11ce-bfc1-08002be10318}",
                    VolumeMountings = new List<string>()
                };

                PnpSafeEjectBackend.ResolveTargetSeam = delegate(DeviceIdentity d, out string targetId, out uint devInst, out string rejectReason)
                {
                    targetId = d.PhysicalUsbParentInstanceId;
                    devInst = 0x1234;
                    rejectReason = null;
                    return true;
                };

                PnpSafeEjectBackend.RequestEjectNativeSeam = delegate(uint inst, out PNP_VETO_TYPE vType, IntPtr pVeto, int maxLen)
                {
                    vType = PNP_VETO_TYPE.PNP_VetoTypeUnknown;
                    return PnpSafeEjectBackend.CR_SUCCESS;
                };

                // Inject CR_ACCESS_DENIED (5) on child lookup
                PnpSafeEjectBackend.LocateDevNodeSeam = delegate(string devId, out uint inst)
                {
                    inst = 0;
                    return 5; // CR_ACCESS_DENIED
                };

                var result31C = PnpSafeEjectBackend.EjectDevice(dev31C);

                bool pass31C = (!result31C.Success) &&
                               (result31C.AggregateResult == DeviceEjectResult.VerificationIndeterminate) &&
                               (!result31C.PostVerificationPassed) &&
                               (result31C.StatusMessage != null && result31C.StatusMessage.Contains("indeterminate"));

                if (!pass31C)
                {
                    failures.Add(string.Format("Test 31C Failed: Lookup error did not fail closed. Success={0}, Aggregate={1}, PostVerifyPassed={2}, Msg={3}",
                        result31C.Success, result31C.AggregateResult, result31C.PostVerificationPassed, result31C.StatusMessage));
                    log("  FAILED: PnP safe eject post-verification treated native lookup error as confirmed removal.");
                }
                else
                {
                    log("  PASSED: Native CM_Locate_DevNodeW lookup error cleanly failed closed as VerificationIndeterminate with Success=false; zero false claims of safe removal.");
                }
            }
            finally
            {
                PnpSafeEjectBackend.ResetSeams();
                SystemDeviceSafetyGuard.ResetForTest();
                DeviceEnforcementLifecycleManager.DisableTestMode();
                RegistryTransactionHelper.KeyPathRewriter = null;
                RegistryTransactionHelper.HiveOverride = null;
            }
        }

        public static void RunPhase61Stage2Tests(Action<string> log, List<string> failures)
        {
            log("");
            log("================================================================================");
            log("  [Test 32] v2.1 Phase 6.1 Stage 2 Identity, Classification & Lifecycle Suite");
            log("  Permanent Regression Suite for Synthetic Bus Prefixes, Fixed-Bit Flash Drives,");
            log("  USB Hub Trust Isolation, State Verifier Precedence & Silent Auto-Lock");
            log("================================================================================");

            DeviceEnforcementLifecycleManager.IsTestMode = true;
            DeviceEnforcementLifecycleManager.ResetForTest();

            try
            {
                // ── TEST 32A: Synthetic Bus Hex Prefix Rejection & Genuine Serial Resolution (Vector 07) ──
                log("[Test 32A] Synthetic Bus Hex Prefix Rejection & Genuine Hex Serial Resolution (Vector 07)...");
                // 1. Synthetic bus hex prefix like 7&2b9187a&0 must be rejected (return null serial)
                var devSynthetic1 = new DeviceIdentity
                {
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_GENERIC&PROD_USB_DISK\7&2B9187A&0"
                };
                DeviceIdentityResolver.Resolve(devSynthetic1);

                // 2. Synthetic bus hex prefix like 0&1234&0 must be rejected
                var devSynthetic2 = new DeviceIdentity
                {
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_GENERIC&PROD_USB_DISK\0&12345678&0"
                };
                DeviceIdentityResolver.Resolve(devSynthetic2);

                // 3. Genuine hardware serial with &0 LUN suffix and valid hex characters (including ABCDEFGH) must succeed
                var devGenuine1 = new DeviceIdentity
                {
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_SANDISK&PROD_ULTRA\00ABCDEF98765432&0"
                };
                DeviceIdentityResolver.Resolve(devGenuine1);

                // 4. Candidate with lingering & after stripping last & must be rejected
                var devLingeringAmp = new DeviceIdentity
                {
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_SANDISK&PROD_ULTRA\PART1&PART2&0"
                };
                DeviceIdentityResolver.Resolve(devLingeringAmp);

                bool pass32A = (string.IsNullOrEmpty(devSynthetic1.SerialNumber)) &&
                               (string.IsNullOrEmpty(devSynthetic2.SerialNumber)) &&
                               (devGenuine1.SerialNumber == "00ABCDEF98765432") &&
                               (string.IsNullOrEmpty(devLingeringAmp.SerialNumber));

                if (!pass32A)
                {
                    failures.Add(string.Format("Test 32A Failed: Serial extraction failed. syn1='{0}', syn2='{1}', gen1='{2}', ling='{3}'",
                        devSynthetic1.SerialNumber, devSynthetic2.SerialNumber, devGenuine1.SerialNumber, devLingeringAmp.SerialNumber));
                    log("  FAILED: Synthetic bus IDs accepted or genuine hardware hex serial falsely rejected.");
                }
                else
                {
                    log("  PASSED: Synthetic bus hex prefix rejected, lingering ampersand topology rejected, and genuine hardware serial with hex characters verified.");
                }

                // ── TEST 32B: Fixed-Bit Large Flash Drive Keyword Classification (Vector 08A) ──
                log("[Test 32B] Fixed-Bit Large Flash Drive Keyword Classification (Vector 08A)...");
                // 1. Fixed-bit 512GB drive with FriendlyName containing "Ultra Fit" -> classified as UsbFlashDrive
                var devFlash1 = new DeviceIdentity
                {
                    FriendlyName = "SanDisk Ultra Fit USB Device",
                    WindowsClass = StorageClass.DiskDrive,
                    PhysicalTransport = PhysicalBusType.Usb,
                    IsRemovableMedia = false,
                    HasSeekPenalty = null,
                    TotalSizeBytes = 512L * 1024L * 1024L * 1024L // 512 GB (> 128 GB)
                };
                var cat1 = DeviceClassifier.Classify(devFlash1);

                // 2. Fixed-bit 256GB drive with Model containing "Cruzer" -> classified as UsbFlashDrive
                var devFlash2 = new DeviceIdentity
                {
                    FriendlyName = "SanDisk SanDisk Cruzer Blade",
                    Model = "Cruzer Blade USB Device",
                    WindowsClass = StorageClass.DiskDrive,
                    PhysicalTransport = PhysicalBusType.Usb,
                    IsRemovableMedia = false,
                    HasSeekPenalty = null,
                    TotalSizeBytes = 256L * 1024L * 1024L * 1024L // 256 GB
                };
                var cat2 = DeviceClassifier.Classify(devFlash2);

                // 3. Fixed-bit 512GB drive with generic name -> classified as ExternalUsbSsd
                var devExternalSsd = new DeviceIdentity
                {
                    FriendlyName = "Samsung Portable SSD T7",
                    Model = "Samsung T7 SCSI Disk Device",
                    WindowsClass = StorageClass.DiskDrive,
                    PhysicalTransport = PhysicalBusType.Usb,
                    IsRemovableMedia = false,
                    HasSeekPenalty = null,
                    TotalSizeBytes = 512L * 1024L * 1024L * 1024L // 512 GB
                };
                var cat3 = DeviceClassifier.Classify(devExternalSsd);

                bool pass32B = (cat1 == DeviceCategory.UsbFlashDrive) &&
                               (cat2 == DeviceCategory.UsbFlashDrive) &&
                               (cat3 == DeviceCategory.ExternalUsbSsd);

                if (!pass32B)
                {
                    failures.Add(string.Format("Test 32B Failed: Classification mismatch. cat1={0}, cat2={1}, cat3={2}",
                        cat1, cat2, cat3));
                    log("  FAILED: Fixed-bit flash drive keyword classification failed.");
                }
                else
                {
                    log("  PASSED: Large fixed-bit flash drives correctly classified via keyword heuristics while external SSDs remain ExternalUsbSsd.");
                }

                // ── TEST 32C: Prohibit USB Hub & Host Controller Trust Inheritance (Vector 08B) ──
                log("[Test 32C] Prohibit USB Hub & Host Controller Trust Inheritance (Vector 08B)...");
                // Rule created targeting a USB Hub device instance ID
                var hubRule = new DeviceRule
                {
                    RuleId = "rule-hub-01",
                    TargetInstanceId = @"USB\VID_0451&PID_8142\HUB_PORT_01",
                    MatchType = RuleMatchType.DeviceInstanceId
                };

                // Arriving child USB storage device attached to the hub
                var childDevFromHub = new DeviceIdentity
                {
                    FriendlyName = "Untrusted Flash on Hub",
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_SANDISK&PROD_ULTRA\0001&0",
                    PhysicalUsbParentInstanceId = @"USB\VID_0451&PID_8142\HUB_PORT_01" // Hub parent
                };

                // Child must NOT match the hub rule
                bool hubMatchesChild = hubRule.Matches(childDevFromHub);

                // Composite device parent (e.g. multi-function USB storage device parent)
                var compositeRule = new DeviceRule
                {
                    RuleId = "rule-composite-01",
                    TargetInstanceId = @"USB\VID_0781&PID_5583\1234567890ABCDEF",
                    MatchType = RuleMatchType.DeviceInstanceId
                };

                var childDevFromComposite = new DeviceIdentity
                {
                    FriendlyName = "Composite Storage Function",
                    DeviceInstanceId = @"USBSTOR\DISK&VEN_SANDISK&PROD_ULTRA\0002&0",
                    PhysicalUsbParentInstanceId = @"USB\VID_0781&PID_5583\1234567890ABCDEF"
                };

                // Child MUST match composite parent rule
                bool compositeMatchesChild = compositeRule.Matches(childDevFromComposite);

                bool pass32C = (!hubMatchesChild) && compositeMatchesChild;

                if (!pass32C)
                {
                    failures.Add(string.Format("Test 32C Failed: Trust inheritance isolation failed. hubMatches={0}, compositeMatches={1}",
                        hubMatchesChild, compositeMatchesChild));
                    log("  FAILED: USB Hub trust inherited by child device or composite parent trust failed.");
                }
                else
                {
                    log("  PASSED: USB Hub and Host Controller trust inheritance strictly prohibited; composite device parent matching preserved.");
                }

                // ── TEST 32D: State Verifier Precedence & Default Fallback (Vector 09) ──
                log("[Test 32D] State Verifier Precedence & Default Fallback (Vector 09)...");
                RegistryTransactionHelper.HiveOverride = RegistryHive.CurrentUser;
                RegistryTransactionHelper.KeyPathRewriter = delegate(string p) { return @"SOFTWARE\USBShieldPro\TestHarness\" + p.Replace('\\', '_'); };
                try
                {
                    // Case 1: Policy has BlockWpdPhonesAndMedia = true AND AutoPlayGuard = true.
                    // Set registry values so both are applied and verified.
                    // Because BlockWpdPhonesAndMedia sets anyPendingReconnect = true,
                    // anyPendingReconnect must be evaluated BEFORE AutoPlayGuard!
                    var pol32D = new ProtectionPolicy
                    {
                        BlockWpdPhonesAndMedia = true,
                        AutoPlayGuard = true
                    };

                    string wpdRawPath = WindowsSecurityConstants.RemovableStoragePoliciesPath + "\\" + WindowsSecurityConstants.GuidWindowsPortableDevices;
                    string wpdPath = RegistryTransactionHelper.KeyPathRewriter(wpdRawPath);
                    string apRawPath = AutoPlayPolicyBackend.AutoPlayHandlersKeyPath;
                    string apPath = RegistryTransactionHelper.KeyPathRewriter(apRawPath);
                    string expRawPath = AutoPlayPolicyBackend.ExplorerPoliciesKeyPath;
                    string expPath = RegistryTransactionHelper.KeyPathRewriter(expRawPath);

                    using (var baseKey = RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64))
                    {
                        using (var sk = baseKey.CreateSubKey(wpdPath))
                        {
                            sk.SetValue(WindowsSecurityConstants.ValueDenyRead, 1, RegistryValueKind.DWord);
                            sk.SetValue(WindowsSecurityConstants.ValueDenyWrite, 1, RegistryValueKind.DWord);
                        }
                        using (var sk = baseKey.CreateSubKey(apPath))
                        {
                            sk.SetValue(WindowsSecurityConstants.ValueDisableAutoplay, 1, RegistryValueKind.DWord);
                        }
                        using (var sk = baseKey.CreateSubKey(expPath))
                        {
                            sk.SetValue(WindowsSecurityConstants.ValueNoAutoplayfornonVolume, 1, RegistryValueKind.DWord);
                        }
                    }

                    var rep32D = StateVerifier.Verify(pol32D);
                    bool passPendingPrecedence = (rep32D.OverallState == ActivationState.PendingReconnect);

                    // Case 2: Only AutoPlayGuard is active and verified.
                    // With no storage/WPD policies, anyPendingReconnect is false.
                    // OverallState must be AppliedAndVerified.
                    var polAutoPlayOnly = new ProtectionPolicy
                    {
                        AutoPlayGuard = true
                    };
                    var repAutoPlayOnly = StateVerifier.Verify(polAutoPlayOnly);
                    bool passAutoPlayApplied = (repAutoPlayOnly.OverallState == ActivationState.AppliedAndVerified);

                    bool pass32D = passPendingPrecedence && passAutoPlayApplied;
                    if (!pass32D)
                    {
                        failures.Add(string.Format("Test 32D Failed: StateVerifier precedence failed. passPending={0} (state={1}), passAutoPlay={2} (state={3})",
                            passPendingPrecedence, rep32D.OverallState, passAutoPlayApplied, repAutoPlayOnly.OverallState));
                        log("  FAILED: AutoPlayGuard masked PendingReconnect or AutoPlay-only verification failed.");
                    }
                    else
                    {
                        log("  PASSED: PendingReconnect takes precedence over AutoPlayGuard, and AutoPlay-only reports AppliedAndVerified.");
                    }
                }
                finally
                {
                    try
                    {
                        using (var baseKey = RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64))
                        {
                            baseKey.DeleteSubKeyTree(@"SOFTWARE\USBShieldPro\TestHarness", false);
                        }
                    }
                    catch { }
                    RegistryTransactionHelper.KeyPathRewriter = null;
                    RegistryTransactionHelper.HiveOverride = null;
                }
            }
            finally
            {
                DeviceEnforcementLifecycleManager.DisableTestMode();
                DeviceEnforcementLifecycleManager.ResetForTest();
            }
        }

        public static void RunPhase62Stage3Tests(Action<string> log, List<string> failures)
        {
            log("");
            log("================================================================================");
            log("  [Test 33] v2.1 Phase 6.2 Stage 3 UI Resource, Handle Hygiene & Theme Suite");
            log("  Permanent Regression Suite for Safe Control Disposal, ThemeChanged Hygiene,");
            log("  Win32 ToolTip/HICON Lifecycle, and FollowWindows DWM Theme Resolution");
            log("================================================================================");

            // ── TEST 33A: Safe Control Disposal Helper (Vector 11A) ──
            log("[Test 33A] Safe Control Disposal Helper with KeepAlive Exemption (Vector 11A)...");
            using (Panel testContainer = new Panel())
            {
                Button btn1 = new Button { Name = "btn1" };
                Button btnKeepAlive = new Button { Name = "btnKeepAlive" };
                Button btn3 = new Button { Name = "btn3" };
                testContainer.Controls.Add(btn1);
                testContainer.Controls.Add(btnKeepAlive);
                testContainer.Controls.Add(btn3);

                UiDrawingUtils.ClearAndDisposeControls(testContainer.Controls, btnKeepAlive);

                bool pass33A = (testContainer.Controls.Count == 0) &&
                               btn1.IsDisposed &&
                               (!btnKeepAlive.IsDisposed) &&
                               btn3.IsDisposed;

                btnKeepAlive.Dispose();

                if (!pass33A)
                {
                    failures.Add(string.Format("Test 33A Failed: ClearAndDisposeControls failed. count={0}, b1Disp={1}, keepDisp={2}, b3Disp={3}",
                        testContainer.Controls.Count, btn1.IsDisposed, btnKeepAlive.IsDisposed, btn3.IsDisposed));
                    log("  FAILED: Non-exempt controls were not disposed or keepAlive control was wrongly disposed.");
                }
                else
                {
                    log("  PASSED: ClearAndDisposeControls cleanly disposed non-exempt controls and spared keepAlive instance.");
                }
            }

            // ── TEST 33B: Win32 HICON / Bitmap Handle Hygiene (Vector 11D) ──
            log("[Test 33B] Win32 HICON Lifecycle & Cloned Icon Integrity (Vector 11D)...");
            using (Bitmap testBmp = new Bitmap(16, 16))
            {
                using (Graphics g = Graphics.FromImage(testBmp))
                {
                    g.Clear(Color.Blue);
                }

                Icon generatedIcon = BrandAssets.CreateIconFromBitmap(testBmp);
                bool pass33B = (generatedIcon != null) &&
                               (generatedIcon.Width == 16) &&
                               (generatedIcon.Height == 16) &&
                               (generatedIcon.Handle != IntPtr.Zero);

                if (generatedIcon != null)
                {
                    generatedIcon.Dispose();
                }

                if (!pass33B)
                {
                    failures.Add("Test 33B Failed: CreateIconFromBitmap failed to generate a valid cloned icon.");
                    log("  FAILED: CreateIconFromBitmap returned null or invalid handle.");
                }
                else
                {
                    log("  PASSED: CreateIconFromBitmap generated valid cloned Icon and safely released unmanaged HICON handle.");
                }
            }

            // ── TEST 33C: ThemeManager FollowWindows Resolution & Event Trigger (Vector 12) ──
            log("[Test 33C] FollowWindows Resolution via Registry Seam & SettingChange Event (Vector 12)...");
            var originalSeam = ThemeManager.RegistryReaderSeam;
            var originalTheme = ThemeManager.CurrentTheme;
            try
            {
                // 1. Simulate Windows Light Mode (AppsUseLightTheme = 1)
                ThemeManager.RegistryReaderSeam = () => 1;
                IThemePalette palLight = ThemeManager.ResolveTheme(AppTheme.FollowWindows);
                bool passLight = (palLight != null) && (!palLight.IsDark);

                // 2. Simulate Windows Dark Mode (AppsUseLightTheme = 0)
                ThemeManager.RegistryReaderSeam = () => 0;
                IThemePalette palDark = ThemeManager.ResolveTheme(AppTheme.FollowWindows);
                bool passDark = (palDark != null) && palDark.IsDark;

                // 3. Test OnWindowsSettingChanged event dispatch
                ThemeManager.SetTheme(AppTheme.FollowWindows, false);
                int themeChangedEvents = 0;
                EventHandler testHandler = delegate { themeChangedEvents++; };
                ThemeManager.ThemeChanged += testHandler;

                // Switch registry seam from dark (0) to light (1) and signal WM_SETTINGCHANGE
                ThemeManager.RegistryReaderSeam = () => 1;
                ThemeManager.OnWindowsSettingChanged();
                ThemeManager.ThemeChanged -= testHandler;

                bool pass33C = passLight && passDark && (themeChangedEvents == 1) && (!ThemeManager.ActivePalette.IsDark);
                if (!pass33C)
                {
                    failures.Add(string.Format("Test 33C Failed: FollowWindows resolution failed. passLight={0}, passDark={1}, events={2}, isDark={3}",
                        passLight, passDark, themeChangedEvents, ThemeManager.ActivePalette.IsDark));
                    log("  FAILED: FollowWindows did not dynamically track simulated Windows theme changes.");
                }
                else
                {
                    log("  PASSED: FollowWindows dynamically resolved Light and Dark palettes and fired ThemeChanged on setting change.");
                }
            }
            finally
            {
                ThemeManager.RegistryReaderSeam = originalSeam;
                ThemeManager.SetTheme(originalTheme, false);
            }

            // ── TEST 33D: Settings Theme Dropdown 6-Option Mapping (Vector 12) ──
            log("[Test 33D] Settings Theme Dropdown 6-Option Bi-directional Mapping (Vector 12)...");
            AppTheme[] expectedThemeOrder = new AppTheme[]
            {
                AppTheme.Porcelain,     // 0: Modern Light
                AppTheme.CharcoalRed,   // 1: Signature Dark
                AppTheme.Graphite,      // 2: Slate
                AppTheme.Midnight,      // 3: Deep Navy
                AppTheme.Cloud,         // 4: Emerald
                AppTheme.FollowWindows  // 5: Follow Windows
            };

            bool passMapping = true;
            for (int i = 0; i < expectedThemeOrder.Length; i++)
            {
                AppTheme mappedTheme = (i == 5) ? AppTheme.FollowWindows :
                    (i == 0 ? AppTheme.Porcelain :
                    (i == 1 ? AppTheme.CharcoalRed :
                    (i == 2 ? AppTheme.Graphite :
                    (i == 3 ? AppTheme.Midnight : AppTheme.Cloud))));

                if (mappedTheme != expectedThemeOrder[i])
                {
                    passMapping = false;
                    break;
                }
            }

            if (!passMapping)
            {
                failures.Add("Test 33D Failed: Theme dropdown index mapping is inconsistent with AppTheme enum.");
                log("  FAILED: Theme dropdown index to AppTheme mapping mismatch.");
            }
            else
            {
                log("  PASSED: 6-option theme dropdown correctly maps Index 5 <-> AppTheme.FollowWindows.");
            }

            // ── TEST 33E: Named ThemeChanged Handlers & Clean Component Disposal (Vector 11B) ──
            log("[Test 33E] Named ThemeChanged Subscriptions & Clean Disposal Hygiene (Vector 11B)...");
            bool passDisposal = true;
            try
            {
                using (var card = new SummaryMetricCard()) { }
                using (var bar = new SafetyMessageBar()) { }
                using (var act = new RecentActivityPanel()) { }
                using (var prot = new ProtectionOverviewPanel()) { }
                using (var sem = new RecoverySemanticsMessageBar()) { }
                using (var art = new RecoveryArtifactRow("key", "tooltip")) { }
                using (var cardArt = new RecoveryArtifactsCard()) { }
                using (var scopeRow = new RecoveryScopeItemRow(new RegistryOriginalValue { KeyPath = @"SOFTWARE\Test", ValueName = "Val" })) { }
            }
            catch (Exception ex)
            {
                passDisposal = false;
                failures.Add("Test 33E Failed: Component creation/disposal threw exception: " + ex.Message);
            }

            if (!passDisposal)
            {
                log("  FAILED: Component disposal or event unhooking failed.");
            }
            else
            {
                log("  PASSED: SummaryMetricCard, SafetyMessageBar, Panels, and RecoveryControls cleanly instantiate and dispose without leaks.");
            }

            // ── TEST 33F: Temporary Access Button Visibility & Cancel Width Dynamic Fit (Bug 2 Regression) ──
            log("[Test 33F] Temporary Access Button Visibility & Cancel Button Width Dynamic Fit...");
            bool pass33F = true;
            using (var tempModule = new CompactTemporaryAccessModule())
            {
                tempModule.RightToLeft = RightToLeft.Yes;
                // Activate temporary access: 300 seconds remaining
                tempModule.SetState(true, true, 300);

                if (tempModule.Btn5Min.Visible || tempModule.Btn15Min.Visible || tempModule.Btn30Min.Visible)
                {
                    pass33F = false;
                    failures.Add(string.Format("Test 33F Failed: Duration buttons remain visible when temporary access is active. 5m={0}, 15m={1}, 30m={2}",
                        tempModule.Btn5Min.Visible, tempModule.Btn15Min.Visible, tempModule.Btn30Min.Visible));
                }

                if (!tempModule.BtnCancel.Visible)
                {
                    pass33F = false;
                    failures.Add("Test 33F Failed: Cancel button is not visible when temporary access is active.");
                }

                int measuredCancelW = AppButton.CalculateWidth(tempModule.BtnCancel.Text, ButtonSize.Small, true);
                if (tempModule.BtnCancel.Width < measuredCancelW)
                {
                    pass33F = false;
                    failures.Add(string.Format("Test 33F Failed: Cancel button width ({0}px) is less than required text width ({1}px) causing text clipping.",
                        tempModule.BtnCancel.Width, measuredCancelW));
                }

                // Restore inactive state: duration buttons must become visible again and cancel button hidden
                tempModule.SetState(true, false, 0);
                if (!tempModule.Btn5Min.Visible || !tempModule.Btn15Min.Visible || !tempModule.Btn30Min.Visible || tempModule.BtnCancel.Visible)
                {
                    pass33F = false;
                    failures.Add("Test 33F Failed: Duration buttons not restored to visible or cancel button not hidden after deactivation.");
                }
            }

            if (!pass33F)
            {
                log("  FAILED: Temporary access buttons visibility or cancel button width verification failed.");
            }
            else
            {
                log("  PASSED: CompactTemporaryAccessModule hides duration buttons, displays cancel button with dynamic unclipped width, and cleanly restores on deactivation.");
            }

            // ── TEST 33G: MainForm Language Toggle Layout Stability & Non-Zero Bounds (Bug 1 Regression) ──
            log("[Test 33G] MainForm Language Toggle Layout Stability & Non-Zero Bounds...");
            bool pass33G = true;
            Language origLang = Loc.Current;
            try
            {
                using (var form = new MainForm())
                {
                    form.Visible = true;
                    form.CreateControl(); // Ensure handle is created
                    form.TriggerToggleLanguage();

                    Panel cp = form.ContentContainer;
                    if (cp == null || !cp.Visible || cp.Width <= 0 || cp.Height <= 0)
                    {
                        pass33G = false;
                        failures.Add(string.Format("Test 33G Failed: ContentContainer is null, invisible, or has non-positive bounds after language toggle: {0}",
                            cp == null ? "null" : string.Format("Vis={0}, Bounds={1}", cp.Visible, cp.Bounds)));
                    }
                    else
                    {
                        if (cp.Controls.Count == 0)
                        {
                            pass33G = false;
                            failures.Add("Test 33G Failed: ContentContainer has 0 child tab controls after language toggle.");
                        }
                        else
                        {
                            Control activeTab = cp.Controls[0];
                            if (!activeTab.Visible || activeTab.Width <= 0 || activeTab.Height <= 0)
                            {
                                pass33G = false;
                                failures.Add(string.Format("Test 33G Failed: Active tab panel is invisible or has non-positive bounds: Vis={0}, Bounds={1}",
                                    activeTab.Visible, activeTab.Bounds));
                            }
                        }
                    }

                    // Toggle back to restore original language preference cleanly
                    form.TriggerToggleLanguage();
                }
            }
            catch (Exception ex)
            {
                pass33G = false;
                failures.Add("Test 33G Failed: Language toggle threw exception: " + ex.Message);
            }
            finally
            {
                Loc.Current = origLang;
            }

            if (!pass33G)
            {
                log("  FAILED: MainForm language toggle left client area unlaid out or blank.");
            }
            else
            {
                log("  PASSED: MainForm.TriggerToggleLanguage() maintains immediate visibility and non-zero layout bounds on content panel and active tab.");
            }

            // ── TEST 33H: Header Layout Non-Overlap, Safety Bar Headroom & Activity RTL Directionality ──
            log("[Test 33H] Header Layout Collision Prevention, Safety Bar Headroom & Activity RTL Directionality...");
            bool pass33H = true;
            try
            {
                // 1. SafetyMessageBar GetPreferredHeight verification
                using (var bar = new SafetyMessageBar())
                {
                    int minH = DpiManager.ScaleInt(46);
                    int prefH = bar.GetPreferredHeight(DpiManager.ScaleInt(600));
                    if (prefH < minH)
                    {
                        pass33H = false;
                        failures.Add(string.Format("Test 33H Failed: SafetyMessageBar.GetPreferredHeight ({0}px) is less than required minimum ({1}px).", prefH, minH));
                    }
                }

                // 1b. ProtectionStatusCard dynamic height with multi-line subtitle
                using (var card = new ProtectionStatusCard())
                {
                    string longSub = Loc.Get("ConflictClassStorageOverridePrompt");
                    card.SetStatus("Attention Required", longSub, StatusBadgeVariant.Warning, false, false, false);
                    int prefH = card.GetPreferredHeight(DpiManager.ScaleInt(600));
                    int baseH = DpiManager.ScaleInt(72);
                    if (prefH <= baseH)
                    {
                        pass33H = false;
                        failures.Add(string.Format("Test 33H Failed: ProtectionStatusCard.GetPreferredHeight ({0}px) did not expand beyond base height ({1}px) for multi-line subtitle.", prefH, baseH));
                    }
                }

                // 2. RecentActivityPanel RTL SetRecords verification
                using (var actPanel = new RecentActivityPanel())
                {
                    actPanel.SetRecords(new List<ActivityRecord>
                    {
                        new ActivityRecord(DateTime.Now, "USB storage unlocked", "Kingston 3.0", ActivityCategory.Protection) { ResultBadge = "Allowed" }
                    }, true);

                    if (actPanel.RightToLeft != RightToLeft.Yes)
                    {
                        pass33H = false;
                        failures.Add("Test 33H Failed: RecentActivityPanel.RightToLeft was not set to Yes when isRtl is true.");
                    }
                }

                // 3. MainForm Header Layout Overlap Detection across Devices and Whitelist
                using (var form = new MainForm())
                {
                    form.Size = new Size(1000, 700);
                    form.CreateControl();

                    for (int step = 0; step < 2; step++)
                    {
                        string currentLangName = Loc.IsRtl ? "Arabic (RTL)" : "English (LTR)";

                        // Switch to Devices Tab (Index 1)
                        form.TriggerSwitchTab(1);
                        Panel devHeader = form.DevicesHeaderPanel;
                        if (devHeader != null)
                        {
                            devHeader.Width = 800;
                            var controls = new Control[] { form.BtnRefreshDevices, form.BtnEjectAllDevices, form.DevicesFilterDropdown, form.DevicesSearchControl };
                            for (int i = 0; i < controls.Length; i++)
                            {
                                for (int j = i + 1; j < controls.Length; j++)
                                {
                                    if (controls[i] != null && controls[j] != null && controls[i].Visible && controls[j].Visible)
                                    {
                                        if (controls[i].Bounds.IntersectsWith(controls[j].Bounds))
                                        {
                                            pass33H = false;
                                            failures.Add(string.Format("Test 33H Failed: Controls '{0}' and '{1}' collide in Devices header under {2}: {3} vs {4}",
                                                controls[i].GetType().Name, controls[j].GetType().Name, currentLangName, controls[i].Bounds, controls[j].Bounds));
                                        }
                                    }
                                }
                            }
                        }

                        // Switch to Whitelist Tab (Index 3)
                        form.TriggerSwitchTab(3);
                        Panel trustHeader = form.TrustedHeaderPanel;
                        if (trustHeader != null)
                        {
                            trustHeader.Width = 800;
                            var controls = new Control[] { form.BtnRefreshTrusted, form.BtnAddTrustedDevice, form.TrustedFilterDropdown, form.TrustedSearchControl };
                            for (int i = 0; i < controls.Length; i++)
                            {
                                for (int j = i + 1; j < controls.Length; j++)
                                {
                                    if (controls[i] != null && controls[j] != null && controls[i].Visible && controls[j].Visible)
                                    {
                                        if (controls[i].Bounds.IntersectsWith(controls[j].Bounds))
                                        {
                                            pass33H = false;
                                            failures.Add(string.Format("Test 33H Failed: Controls '{0}' and '{1}' collide in Whitelist header under {2}: {3} vs {4}",
                                                controls[i].GetType().Name, controls[j].GetType().Name, currentLangName, controls[i].Bounds, controls[j].Bounds));
                                        }
                                    }
                                }
                            }

                            // Verify Whitelist vertical stacking order (Header at Y=0, SummaryStrip below it)
                            if (form.TrustedSummaryStrip != null)
                            {
                                if (trustHeader.Top != 0)
                                {
                                    pass33H = false;
                                    failures.Add(string.Format("Test 33H Failed: TrustedHeaderPanel.Top is {0} instead of 0 in {1}.", trustHeader.Top, currentLangName));
                                }
                                if (form.TrustedSummaryStrip.Top < trustHeader.Bottom)
                                {
                                    pass33H = false;
                                    failures.Add(string.Format("Test 33H Failed: TrustedSummaryStrip.Top ({0}) is above TrustedHeaderPanel.Bottom ({1}) in {2}.",
                                        form.TrustedSummaryStrip.Top, trustHeader.Bottom, currentLangName));
                                }
                            }

                            // Verify search box width can expand to >= 200px when window width allows
                            form.Size = new Size(1300, 700);
                            if (form.TrustedSearchControl != null && form.TrustedSearchControl.Width < DpiManager.ScaleInt(200))
                            {
                                pass33H = false;
                                failures.Add(string.Format("Test 33H Failed: TrustedSearchControl width is {0}px, expected >= {1}px in 1300px window under {2}.",
                                    form.TrustedSearchControl.Width, DpiManager.ScaleInt(200), currentLangName));
                            }
                        }

                        // Toggle language for second iteration
                        if (step == 0)
                        {
                            form.TriggerToggleLanguage();
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                pass33H = false;
                failures.Add("Test 33H Failed: Header layout verification threw exception: " + ex.Message);
            }
            finally
            {
                Loc.Current = origLang;
            }

            if (!pass33H)
            {
                log("  FAILED: Header toolbar controls collide or SafetyMessageBar/RecentActivity RTL layout failed.");
            }
            else
            {
                log("  PASSED: Header layouts prevent control collision in LTR/RTL, SafetyMessageBar provides >=46px headroom, and RecentActivity handles RTL cleanly.");
            }
        }
    }
}

#endif // !PRODUCTION
